window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s13-94","number":94,"surah":13,"verses":[24],"verseLabel":"الرعد: 24","question":"لماذا عُدّي السلام بـ﴿على﴾ لا باللام؟","answer":"لأن «على» هي الصيغة المألوفة للتحية، وفيها إيحاء بحلول السلام وإحاطته بالمسلَّم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص152.","url":""}]},{"id":"s13-95","number":95,"surah":13,"verses":[24],"verseLabel":"الرعد: 24","question":"لماذا نسبت الملائكة الفوز إلى الصبر: ﴿بِمَا صَبَرْتُمْ﴾؟","answer":"لأنه الجامع الذي يحفظ جميع خصالهم: لا وفاء ولا صلاة ولا إحسان بلا صبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص153.","url":""}]},{"id":"s13-96","number":96,"surah":13,"verses":[25],"verseLabel":"الرعد: 25","question":"لماذا جاءت الواو في ﴿وَيُفْسِدُونَ فِي الْأَرْضِ﴾ هنا، وحُذفت في نظير البقرة؟","answer":"سياق الرعد يعدد جرائم مستقلة متعاطفة، أما سياق البقرة فجاءت الصفات أشد اتصالًا في تصوير نتيجة النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص157؛ مسح عكسي.","url":""}]},{"id":"s13-97","number":97,"surah":13,"verses":[25],"verseLabel":"الرعد: 25","question":"ما سرّ التعبير بقوله تعالى: ﴿لَهُمُ اللَّعْنَةُ﴾ لا «عليهم اللعنة»؟","answer":"اللام تثبت اختصاصهم واستحقاقهم لها، لا مجرد نزولها عليهم في لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص162.","url":""}]},{"id":"s13-98","number":98,"surah":13,"verses":[26],"verseLabel":"الرعد: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿يَبْسُطُ الرِّزْقَ... وَيَقْدِرُ﴾ لا يوسع ويضيق؟","answer":"البسط يصور نشر الرزق، و«يقدر» يدل على تقديره بحد معلوم، لا مجرد التضييق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص167-169.","url":""}]},{"id":"s13-99","number":99,"surah":13,"verses":[26],"verseLabel":"الرعد: 26","question":"لماذا نُكرت ﴿مَتَاعٌ﴾ في ﴿إِلَّا مَتَاعٌ﴾؟","answer":"للتحقير والتقليل: شيء قليل عابر إذا قيس بالآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص172.","url":""}]},{"id":"s13-100","number":100,"surah":13,"verses":[27],"verseLabel":"الرعد: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿يُضِلُّ اللَّهُ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ﴾؟","answer":"علّق الضلال بالمشيئة العادلة، وبيّن في جانب الهداية سبب القبول: الإنابة الصادقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص183-186.","url":""}]},{"id":"s13-101","number":101,"surah":13,"verses":[28],"verseLabel":"الرعد: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿تَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ﴾ بالمضارع؟","answer":"لتصوير السكينة وهي تتجدد كلما تجدد الذكر، لا أثرًا وقع وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص190.","url":""}]},{"id":"s13-102","number":102,"surah":13,"verses":[28],"verseLabel":"الرعد: 28","question":"لماذا سُمّي القرآن ﴿ذِكْرَ اللَّهِ﴾؟","answer":"لأنه يذكّر بالله ووعده وحججه، ويوقظ في القلب حقائق كان يغفل عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص191.","url":""}]},{"id":"s13-103","number":103,"surah":13,"verses":[29],"verseLabel":"الرعد: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿طُوبَى لَهُمْ وَحُسْنُ مَآبٍ﴾؟","answer":"«طوبى» تجمع الخير والغبطة، ثم «حسن مآب» يثبت جمال النهاية والمرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص199-205.","url":""}]},{"id":"s13-104","number":104,"surah":13,"verses":[30],"verseLabel":"الرعد: 30","question":"لماذا اختير اسم ﴿الرَّحْمَن﴾ في ﴿وَهُمْ يَكْفُرُونَ بِالرَّحْمَنِ﴾؟","answer":"لتفظيع كفرهم: يجحدون من عمّت رحمته، فيقابلون الإنعام بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص225-226.","url":""}]},{"id":"s13-105","number":105,"surah":13,"verses":[30],"verseLabel":"الرعد: 30","question":"ما سرّ التعبير في قول النبي ﷺ: ﴿عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ مَتَابِ﴾؟","answer":"قدم الجارين لقصر الاعتماد والرجوع عليه وحده، وجمع عمل القلب ومسار الحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص231-234.","url":""}]},{"id":"s13-106","number":106,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"لماذا رُتبت المعجزات: تسيير الجبال ثم تقطيع الأرض ثم تكليم الموتى؟","answer":"تصاعد من تغيير الجماد الظاهر، إلى شق الأرض، إلى إعادة الحياة والنطق؛ ليبلغ الاقتراح غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص243-250.","url":""}]},{"id":"s13-107","number":107,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿بَلْ لِلَّهِ الْأَمْرُ جَمِيعًا﴾؟","answer":"إضراب عن جدوى اقتراحاتهم إلى الحقيقة الحاكمة: كل أمر الهداية والآيات لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص252-260.","url":""}]},{"id":"s13-108","number":108,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَلَمْ يَيْأَسِ الَّذِينَ آمَنُوا﴾؟","answer":"على معنى: أفلم يعلموا ويتبينوا؛ وهو استعمال عربي ينقلهم من انتظار الآية المقترحة إلى اليقين بسلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص256.","url":""}]},{"id":"s13-109","number":109,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿جَمِيعًا﴾ لا كلهم؟","answer":"«جميعًا» تبرز اجتماعهم على حال واحدة تحت القدرة، لا مجرد استغراق الأفراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص260.","url":""}]},{"id":"s13-110","number":110,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿قَارِعَةٌ﴾ بالإفراد؟","answer":"كل حادثة واحدة منها تكفي لقرعهم وإفزاعهم، فالإفراد يثبت تجدد الجنس مرة بعد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص267-268.","url":""}]},{"id":"s13-111","number":111,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحُلُّ قَرِيبًا مِنْ دَارِهِمْ﴾؟","answer":"﴿تحل﴾ بمعنى تنزل وتقع، وجاءت بالمضارع لاستحضار تجدّد التهديد، و﴿قريبًا من دارهم﴾ توسّع دائرة التخويف؛ فقد لا تقع في دارهم نفسها ولكنها تبلغ من القرب ما يفزعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص270-274.","url":""}]},{"id":"s13-112","number":112,"surah":13,"verses":[31],"verseLabel":"الرعد: 31","question":"لماذا أُفرد وعُرّف ﴿الْمِيعَاد﴾؟","answer":"لأن وعد الله واحد في صدقه وحتمه وإن تعددت صوره، والتعريف يشير إلى الموعد المعلوم المنتظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص281.","url":""}]},{"id":"s13-113","number":113,"surah":13,"verses":[33],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ هُوَ قَائِمٌ عَلَى كُلِّ نَفْسٍ﴾؟","answer":"استفهام يحذف مقابله لوضوحها: هل من يحصي كل عمل كالأصنام العاجزة؟ فالجواب يهدم الشرك بذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص303-311.","url":""}]},{"id":"s13-114","number":114,"surah":13,"verses":[33],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿بِمَا كَسَبَتْ﴾ لا اكتسبت؟","answer":"«كسبت» أعم في الخير والشر، والمقام في إحاطة العلم بكل ما يصدر عن النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص307-309.","url":""}]},{"id":"s13-115","number":115,"surah":13,"verses":[33],"verseLabel":"الرعد: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿شُرَكَاءَ﴾ بالجمع لا أندادًا؟","answer":"يحكي تعدد معبوداتهم وادعاءهم مشاركتها لله في الاستحقاق، ثم يأمرهم بتسميتها عجزًا وتبكيتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص310-311.","url":""}]},{"id":"s13-116","number":116,"surah":13,"verses":[35],"verseLabel":"الرعد: 35","question":"لماذا سُمّيت الجنة ﴿مَثَلُ الْجَنَّةِ﴾؟","answer":"﴿مثل الجنة﴾ أي صفتها وشأنها الذي وُعد به المتقون؛ ثم بيّن من هذه الصفة دوام الأكل والظل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص341.","url":""}]},{"id":"s13-117","number":117,"surah":13,"verses":[35],"verseLabel":"الرعد: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿أُكُلُهَا دَائِمٌ وَظِلُّهَا﴾؟","answer":"اختار الأكل والظل لأنهما أبرز ما ينقطع في بساتين الدنيا، فنفى عنهما الانقطاع ليظهر كمال الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص341-360.","url":""}]},{"id":"s13-118","number":118,"surah":13,"verses":[36],"verseLabel":"الرعد: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿يَفْرَحُونَ بِمَا أُنْزِلَ إِلَيْكَ﴾؟","answer":"المضارع يصور تجدد فرح أهل الكتاب الصادقين كلما وافق الوحي ما عندهم من الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص361-382.","url":""}]},{"id":"s13-119","number":119,"surah":13,"verses":[37],"verseLabel":"الرعد: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿حُكْمًا عَرَبِيًّا﴾ لا كتابًا عربيًا؟","answer":"ليبرز وظيفة القرآن في الفصل والهداية والتشريع، لا مجرد لغته أو صورته المكتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص382.","url":""}]},{"id":"s13-120","number":120,"surah":13,"verses":[38],"verseLabel":"الرعد: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَقَدْ أَرْسَلْنَا رُسُلًا مِنْ قَبْلِكَ﴾؟","answer":"للرد على من عيّر الرسول بالزواج؛ فالرسل قبله كانت لهم أزواج وذرية، وليس ذلك منافيًا للرسالة.","sources":[{"label":"الكرماني، أسرار التكرار، ص153؛ الموسوعة ج24، ص401.","url":""}]},{"id":"s13-121","number":121,"surah":13,"verses":[38],"verseLabel":"الرعد: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا بِإِذْنِ اللَّهِ﴾ وأظهر الاسم؟","answer":"ليقرر أن الآيات لا يملكها رسول استقلالًا، وأن المرجع في كل خرق للعادة إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص401.","url":""}]},{"id":"s13-122","number":122,"surah":13,"verses":[39],"verseLabel":"الرعد: 39","question":"كيف نفهم ﴿يَمْحُو اللَّهُ مَا يَشَاءُ وَيُثْبِتُ﴾ مع ﴿وَعِنْدَهُ أُمُّ الْكِتَابِ﴾؟","answer":"المحو والإثبات فيما يظهر للخلق أو في الصحف التابعة لحكمته، وأصل العلم والكتاب عنده ثابت لا يطرأ عليه جهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص421.","url":""}]},{"id":"s13-123","number":123,"surah":13,"verses":[41],"verseLabel":"الرعد: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿نَأْتِي الْأَرْضَ نَنْقُصُهَا مِنْ أَطْرَافِهَا﴾؟","answer":"صوّر انحسار سلطان الباطل وانتشار دعوة الحق كأرض تؤخذ أطرافها تدريجيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص421-441.","url":""}]},{"id":"s13-124","number":124,"surah":13,"verses":[42],"verseLabel":"الرعد: 42","question":"لماذا وصف تدبيرهم بـ﴿الْمَكْر﴾ ثم قال: ﴿فَلِلَّهِ الْمَكْرُ جَمِيعًا﴾؟","answer":"المكر تدبير خفي؛ وما يملكونه داخل في سلطان الله وعلمه، فيبطل أثره أو يجعله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص441.","url":""}]},{"id":"s13-125","number":125,"surah":13,"verses":[43],"verseLabel":"الرعد: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ﴾ ولم يسمِّهم؟","answer":"الاسم الموصول يعم كل من قامت عنده شهادة الكتاب، ويجعل العبرة بالعلم الذي يشهد لا بالشخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص461.","url":""}]},{"id":"s14-1","number":1,"surah":14,"verses":[1],"verseLabel":"إبراهيم: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتُخْرِجَ النَّاسَ﴾ لا المؤمنين؟","answer":"لأن الرسالة موجهة إلى الناس جميعًا، وإن كان الانتفاع التام لمن استجاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص481.","url":""}]},{"id":"s14-2","number":2,"surah":14,"verses":[1],"verseLabel":"إبراهيم: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿بِإِذْنِ رَبِّهِمْ﴾ لا بإذن الله؟","answer":"عنوان الربوبية يلائم التربية والإخراج من الظلمات إلى النور، ويشعر بعناية ربهم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص485.","url":""}]},{"id":"s14-3","number":3,"surah":14,"verses":[1],"verseLabel":"إبراهيم: 1","question":"لماذا جُمعت ﴿الظلمات﴾ وأُفرد ﴿النور﴾؟","answer":"لأن مسالك الضلال كثيرة متشعبة، والحق في أصله طريق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص486-536.","url":""}]},{"id":"s14-4","number":4,"surah":14,"verses":[1],"verseLabel":"إبراهيم: 1","question":"لماذا خُتم الصراط بـ﴿الْعَزِيزِ الْحَمِيدِ﴾؟","answer":"العزيز غالب لا تُعجزه معارضة، والحميد مستحق للحمد على نعمة الوحي والهداية.","sources":[{"label":"ابن عاشور، التحرير والتنوير، تفسير إبراهيم: 1، ص180–181، [النص المنشور](https://quran.com/ar/ibrahim/1/tafsirs/arabic-tanweer-tafseer).","url":""}]},{"id":"s14-5","number":5,"surah":14,"verses":[2],"verseLabel":"إبراهيم: 2","question":"لماذا وُصف الله بـ﴿الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾؟","answer":"لتفخيم شأنه وإبطال طريق غيره؛ فمن لا يملك شيئًا من الكون لا يستحق أن يُتبع صراطه.","sources":[{"label":"ابن عاشور، التحرير والتنوير، تفسير إبراهيم: 2، ص182، [النص المنشور](https://islamweb.net/ar/library/content/61/1563/).","url":""}]},{"id":"s14-6","number":6,"surah":14,"verses":[2],"verseLabel":"إبراهيم: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿وَوَيْلٌ لِلْكَافِرِينَ مِنْ عَذَابٍ شَدِيدٍ﴾؟","answer":"«من» تبين منشأ الويل: هلاك ناشئ من عذاب شديد، فاجتمع الحكم وسببه.","sources":[{"label":"ابن عاشور، التحرير والتنوير، تفسير إبراهيم: 2، ص182، [النص المنشور](https://islamweb.net/ar/library/content/61/1563/).","url":""}]},{"id":"s14-7","number":7,"surah":14,"verses":[3],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَحِبُّونَ الْحَيَاةَ الدُّنْيَا عَلَى الْآخِرَةِ﴾ لا يحبون؟","answer":"زيادة المبنى تؤكد تعمدهم الإيثار؛ أحبوا الدنيا حبًا جعلهم يقدمونها على الآخرة.","sources":[{"label":"ابن عاشور، التحرير والتنوير، تفسير إبراهيم: 3، [النص المنشور](https://quran-tafsir.net/ashour/sura14-aya3.html).","url":""}]},{"id":"s14-8","number":8,"surah":14,"verses":[3],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يَبْغُونَهَا عِوَجًا﴾ لا ميلًا؟","answer":"العوج يصور طلبهم جعل الطريق المستقيم معوجًا في الاعتقاد والدعوة، فهو أبلغ من مطلق الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص515.","url":""}]},{"id":"s14-9","number":9,"surah":14,"verses":[3],"verseLabel":"إبراهيم: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي ضَلَالٍ بَعِيدٍ﴾؟","answer":"جعل الضلال مكانًا يحيط بهم، و«بعيد» يدل على بعد الرجوع إلى الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص498-515.","url":""}]},{"id":"s14-10","number":10,"surah":14,"verses":[4],"verseLabel":"إبراهيم: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿بِلِسَانِ قَوْمِهِ﴾ وأفرد اللسان؟","answer":"المراد اللغة الجامعة للقوم، فهي لسان واحد من حيث نظام البيان وإن تعددت ألسنة المتكلمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص520.","url":""}]},{"id":"s14-11","number":11,"surah":14,"verses":[4],"verseLabel":"إبراهيم: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيُبَيِّنَ لَهُمْ﴾ بالمضارع؟","answer":"ليدل على استمرار وظيفة البيان وتجددها مع الوقائع والأسئلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص523.","url":""}]},{"id":"s14-12","number":12,"surah":14,"verses":[4],"verseLabel":"إبراهيم: 4","question":"لماذا ختم بـ﴿الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"العزة تناسب نفاذ المشيئة في الإضلال والهداية، والحكمة تنفي العبث والظلم في ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص525-527.","url":""}]},{"id":"s14-13","number":13,"surah":14,"verses":[5],"verseLabel":"إبراهيم: 5","question":"ما سرّ التعبير بقوله تعالى: لموسى: ﴿أَخْرِجْ قَوْمَكَ﴾ لا بني إسرائيل؟","answer":"«قومك» تستحضر رابطة الرسالة والشفقة، وتجعل التكليف مباشرًا بمن أُرسل إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص534.","url":""}]},{"id":"s14-14","number":14,"surah":14,"verses":[5],"verseLabel":"إبراهيم: 5","question":"لماذا جُمعت الظلمات وأُفرد النور مرة أخرى؟","answer":"لتأكيد أن النجاة انتقال من ألوان الاستعباد والجهل إلى هدى واحد مصدره الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص536.","url":""}]},{"id":"s14-15","number":15,"surah":14,"verses":[5],"verseLabel":"إبراهيم: 5","question":"ما المقصود بـ﴿أَيَّامِ اللَّهِ﴾ ولماذا أضيفت إليه؟","answer":"هي أيام تجلي نعمه ونقمه ونصره؛ والإضافة تفخمها لأنها مواضع ظهور تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص541.","url":""}]},{"id":"s14-16","number":16,"surah":14,"verses":[5],"verseLabel":"إبراهيم: 5","question":"لماذا خُتمت بـ﴿لِكُلِّ صَبَّارٍ شَكُورٍ﴾؟","answer":"العبرة بأيام الشدة والنعمة لا يلتقطها إلا كثير الصبر عند البلاء وكثير الشكر عند العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص541-553.","url":""}]},{"id":"s14-17","number":17,"surah":14,"verses":[6],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قول موسى: ﴿اذْكُرُوا نِعْمَةَ اللَّهِ﴾ بالإفراد؟","answer":"«نعمة» اسم جنس يضم أفراد النعم، ثم فُصّل أعظمها بالإنجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص553.","url":""}]},{"id":"s14-18","number":18,"surah":14,"verses":[6],"verseLabel":"إبراهيم: 6","question":"لماذا أمرهم بذكر النعمة لا المنعم؟","answer":"لأن استحضار أثر النعمة المشاهد أقرب لتحريك الشكر، وهو في الوقت نفسه يذكّر بالمنعم لإضافتها إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص554.","url":""}]},{"id":"s14-19","number":19,"surah":14,"verses":[6],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿آلِ فِرْعَوْنَ﴾؟","answer":"«الآل» تستحضر جهاز فرعون وأتباعه الذين باشروا الاستضعاف، لا شخصه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص556.","url":""}]},{"id":"s14-20","number":20,"surah":14,"verses":[6],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يُذَبِّحُونَ أَبْنَاءَكُمْ﴾ لا أولادكم؟","answer":"لأن القتل خُص بالذكور الذين يُخشى منهم، و«الأبناء» يصرح بهذا القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص561.","url":""}]},{"id":"s14-21","number":21,"surah":14,"verses":[6],"verseLabel":"إبراهيم: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَحْيُونَ نِسَاءَكُمْ﴾ بالمضارع؟","answer":"لتصوير استمرار إبقائهن في حياة الذل والخدمة، لا واقعة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص562.","url":""}]},{"id":"s14-22","number":22,"surah":14,"verses":[7],"verseLabel":"إبراهيم: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿لَئِنْ شَكَرْتُمْ لَأَزِيدَنَّكُمْ﴾ وحذف المفعول؟","answer":"ليعم كل زيادة: في النعمة والبركة والتوفيق والرضا، فلا يحصرها في شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص568-571.","url":""}]},{"id":"s14-23","number":23,"surah":14,"verses":[7],"verseLabel":"إبراهيم: 7","question":"لماذا لم يقل صراحة: «ولئن كفرتم لأعذبنكم»؟","answer":"عدل إلى ﴿إن عذابي لشديد﴾ فتحًا لباب التوبة، مع تهديد ثابت لا يربط العذاب آليًا بكل كفر في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص571-572؛ استدراك ج39، ص178.","url":""}]},{"id":"s14-24","number":24,"surah":14,"verses":[8],"verseLabel":"إبراهيم: 8","question":"ما سرّ التعبير في قول موسى: ﴿إِنْ تَكْفُرُوا أَنْتُمْ﴾ مع ذكر الضمير المنفصل؟","answer":"للتوكيد والتخصيص: كفركم لا يضر الله، وإنما تعود عاقبته عليكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص578.","url":""}]},{"id":"s14-25","number":25,"surah":14,"verses":[8],"verseLabel":"إبراهيم: 8","question":"لماذا ختم بـ﴿غَنِيٌّ حَمِيدٌ﴾؟","answer":"غني عن شكرهم، حميد في ذاته وإن كفروا؛ فلا يزيده الشكر ولا ينقصه الجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص578.","url":""}]},{"id":"s14-26","number":26,"surah":14,"verses":[9],"verseLabel":"إبراهيم: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿نَبَأُ الَّذِينَ مِنْ قَبْلِكُمْ﴾ لا خبرهم؟","answer":"النبأ خبر عظيم ذو أثر وعبرة، وهو الأنسب لقصص الأمم المهلكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص584.","url":""}]},{"id":"s14-27","number":27,"surah":14,"verses":[9],"verseLabel":"إبراهيم: 9","question":"لماذا ذُكر نوح وعاد وثمود ثم قيل: ﴿وَالَّذِينَ مِنْ بَعْدِهِمْ﴾؟","answer":"ذكر الخاص الأشهر ثم عمم، ليصل المعلوم بما لا يحصيه إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص585.","url":""}]},{"id":"s14-28","number":28,"surah":14,"verses":[9],"verseLabel":"إبراهيم: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَعْلَمُهُمْ إِلَّا اللَّهُ﴾؟","answer":"ليقطع توهم إحاطة البشر بتاريخ المكذبين، ويجعل كثرتهم نفسها آية وعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص594-595.","url":""}]},{"id":"s14-29","number":29,"surah":14,"verses":[9],"verseLabel":"إبراهيم: 9","question":"ما سر قوله: ﴿فَرَدُّوا أَيْدِيَهُمْ فِي أَفْوَاهِهِمْ﴾؟","answer":"صورة تحتمل كظم الغيظ أو إسكات الرسل أو عض الأنامل؛ وجمع الاحتمالات يرسم عنف الرفض والنفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص594-605.","url":""}]},{"id":"s14-30","number":30,"surah":14,"verses":[9],"verseLabel":"إبراهيم: 9","question":"ما وجه قولهم: ﴿فِي شَكٍّ مِمَّا تَدْعُونَنَا إِلَيْهِ مُرِيبٍ﴾؟","answer":"لم يصفوا أنفسهم بالشك فقط، بل جعلوا المدعو إليه باعثًا للريبة، مبالغة في قلب الحقائق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص601-605.","url":""}]},{"id":"s14-31","number":31,"surah":14,"verses":[10],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قول الرسل: ﴿أَفِي اللَّهِ شَكٌّ﴾ دون «أتشكون في الله»؟","answer":"قدمت الجار والمجرور لتجعل وقوع الشك في الله نفسه موضع إنكار واستبعاد قبل ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص601.","url":""}]},{"id":"s14-32","number":32,"surah":14,"verses":[10],"verseLabel":"إبراهيم: 10","question":"لماذا وصف الله بـ﴿فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"لأن الابتداء بالخلق دليل حاضر يهدم الشك في وحدانيته وقدرته على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص601-606.","url":""}]},{"id":"s14-33","number":33,"surah":14,"verses":[10],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْعُوكُمْ لِيَغْفِرَ لَكُمْ﴾؟","answer":"حوّل الدعوة من مجرد تكليف إلى رحمة غايتها المغفرة، فجمع الترغيب والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص605.","url":""}]},{"id":"s14-34","number":34,"surah":14,"verses":[10],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيُؤَخِّرَكُمْ﴾ لا يمهلكم؟","answer":"التأخير يثبت أجلًا مقدرًا تُنقلون إليه، أما الإمهال فقد يوهم تركًا بلا نهاية مضروبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص605-606.","url":""}]},{"id":"s14-35","number":35,"surah":14,"verses":[10],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿إِلَى أَجَلٍ مُسَمًّى﴾؟","answer":"«إلى» تحدد نهاية الإمهال، و«مسمى» يؤكد أنه معلوم مقدر لا يتقدم ولا يتأخر عبثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص606.","url":""}]},{"id":"s14-36","number":36,"surah":14,"verses":[10],"verseLabel":"إبراهيم: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿تَصُدُّونَا﴾ لا تمنعوننا؟","answer":"الصد يجمع المنع والصرف عن جهة مقصودة، وهي عبادة ما كان يعبد الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص608.","url":""}]},{"id":"s14-37","number":37,"surah":14,"verses":[11],"verseLabel":"إبراهيم: 11","question":"لماذا أضيفت الرسل إلى أقوامهم: ﴿قَالَتْ لَهُمْ رُسُلُهُمْ﴾؟","answer":"لتذكيرهم بأن الرسل منهم، يعرفون صدقهم ولسانهم، فتقوم الحجة أقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص616-617.","url":""}]},{"id":"s14-38","number":38,"surah":14,"verses":[11],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قول الرسل: ﴿إِنْ نَحْنُ إِلَّا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"أقروا بالمماثلة البشرية ثم أبطلوا لوازمها الفاسدة؛ فالنبوة فضل من الله لا خروج عن البشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص618-621.","url":""}]},{"id":"s14-39","number":39,"surah":14,"verses":[11],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿يَمُنُّ عَلَى مَنْ يَشَاءُ مِنْ عِبَادِهِ﴾؟","answer":"المنة تبرز أن الرسالة اصطفاء محض، و«من يشاء» ترد اختيار النبوة إلى الحكمة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص620-621.","url":""}]},{"id":"s14-40","number":40,"surah":14,"verses":[11],"verseLabel":"إبراهيم: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿بِسُلْطَانٍ﴾ نكرة؟","answer":"ليعم أي حجة خارقة يطلبونها؛ فالرسل لا يأتون بشيء منها إلا بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص623.","url":""}]},{"id":"s14-41","number":41,"surah":14,"verses":[11],"verseLabel":"إبراهيم: 11","question":"لماذا أُظهر اسم الله في ﴿وَعَلَى اللَّهِ فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ﴾؟","answer":"لتجديد المهابة وتثبيت موضع الاعتماد، ولئلا يضعف المعنى بضمير بعيد المرجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص625.","url":""}]},{"id":"s14-42","number":42,"surah":14,"verses":[11,12],"verseLabel":"إبراهيم: 11-12","question":"ما سرّ التعبير بقوله تعالى: أولًا: ﴿فَلْيَتَوَكَّلِ الْمُؤْمِنُونَ﴾ ثم ﴿فَلْيَتَوَكَّلِ الْمُتَوَكِّلُونَ﴾؟","answer":"الأولى تؤسس أن الإيمان يوجب التوكل، والثانية تحث من اتصف بالتوكل أن يحقق وصفه عند الأذى.","sources":[{"label":"الكرماني، أسرار التكرار، ص154؛ الموسوعة ج24، ص625-638.","url":""}]},{"id":"s14-43","number":43,"surah":14,"verses":[12],"verseLabel":"إبراهيم: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا لَنَا أَلَّا نَتَوَكَّلَ عَلَى اللَّهِ﴾؟","answer":"استفهام إنكاري يجعل ترك التوكل غير مفهوم بعد أن هداهم الله سبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص627-632.","url":""}]},{"id":"s14-44","number":44,"surah":14,"verses":[12],"verseLabel":"إبراهيم: 12","question":"لماذا جُمعت ﴿سُبُلَنَا﴾؟","answer":"لكثرة طرق الطاعة والثبات التي هدى الله كل رسول ومؤمن إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص632.","url":""}]},{"id":"s14-45","number":45,"surah":14,"verses":[12],"verseLabel":"إبراهيم: 12","question":"لماذا توالت المؤكدات في ﴿وَلَنَصْبِرَنَّ عَلَى مَا آذَيْتُمُونَا﴾؟","answer":"لإعلان عزم لا يتزعزع أمام تهديد الكفار: لام القسم ونون التوكيد واجتماع الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص633.","url":""}]},{"id":"s14-46","number":46,"surah":14,"verses":[12],"verseLabel":"إبراهيم: 12","question":"لماذا حُذف نوع الأذى في ﴿آذَيْتُمُونَا﴾؟","answer":"ليعم القول والفعل والطرد والتهديد وسائر ما لقيه الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص634-635.","url":""}]},{"id":"s14-47","number":47,"surah":14,"verses":[13],"verseLabel":"إبراهيم: 13","question":"ما وجه قول الكفار: ﴿لَنُخْرِجَنَّكُمْ... أَوْ لَتَعُودُنَّ﴾ بهذه المؤكدات؟","answer":"لتصوير بلوغ العناد حد الإكراه، وكأنهم لا يرون للرسل خيارًا ثالثًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص643-646.","url":""}]},{"id":"s14-48","number":48,"surah":14,"verses":[13],"verseLabel":"إبراهيم: 13","question":"كيف يُفهم قولهم: ﴿لَتَعُودُنَّ فِي مِلَّتِنَا﴾ مع أن الرسل لم يكونوا عليها؟","answer":"العود هنا بحسب زعم القوم أو بمعنى الرجوع إلى الحال الاجتماعية السابقة قبل إعلان المفاصلة، لا إثبات الكفر للرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص646-647.","url":""}]},{"id":"s14-49","number":49,"surah":14,"verses":[13],"verseLabel":"إبراهيم: 13","question":"لماذا قدّموا الإخراج على العودة في الملة؟","answer":"لأن الطرد هو التهديد المباشر، ثم جعلوا الرجوع في ملتهم البديل الذي يريدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص646.","url":""}]},{"id":"s14-50","number":50,"surah":14,"verses":[13],"verseLabel":"إبراهيم: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَوْحَى إِلَيْهِمْ رَبُّهُمْ﴾ لا الله؟","answer":"الربوبية تلائم النصرة والرعاية بعد استضعاف الرسل، وإضافة «ربهم» تزيد التثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص648-649.","url":""}]},{"id":"s14-51","number":51,"surah":14,"verses":[13,14],"verseLabel":"إبراهيم: 13-14","question":"لماذا أكّد: ﴿لَنُهْلِكَنَّ الظَّالِمِينَ وَلَنُسْكِنَنَّكُمُ الْأَرْضَ﴾؟","answer":"ليقابل توكيد تهديد الكفار بوعد إلهي أقوى محقق: هلاك الظالم وتمكين الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص649-654.","url":""}]},{"id":"s14-52","number":52,"surah":14,"verses":[14],"verseLabel":"إبراهيم: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَلِكَ لِمَنْ خَافَ مَقَامِي وَخَافَ وَعِيدِ﴾؟","answer":"الأول خوف الوقوف بين يديه وهيبته، والثاني خوف ما توعد به؛ فجمع بين جلال الموقف وألمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص656-658.","url":""}]},{"id":"s14-53","number":53,"surah":14,"verses":[14],"verseLabel":"إبراهيم: 14","question":"ما سرّ تقديم خوف المقام على خوف الوعيد؟","answer":"لأن تعظيم الله أصل، والخوف من العقوبة أثر تابع له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص658.","url":""}]},{"id":"s14-54","number":54,"surah":14,"verses":[15],"verseLabel":"إبراهيم: 15","question":"من الذين ﴿اسْتَفْتَحُوا﴾، ولماذا جاءت الصيغة مزيدة؟","answer":"تحتمل طلب الرسل النصر وطلب الكفار الفصل استهزاء؛ وصيغة الاستفعال تلائم طلب الحكم والفتح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص663.","url":""}]},{"id":"s14-55","number":55,"surah":14,"verses":[15],"verseLabel":"إبراهيم: 15","question":"لماذا جمع بين ﴿جَبَّارٍ عَنِيدٍ﴾؟","answer":"الجبار يتعالى ويقهر الخلق، والعنيد يعاند الحق؛ فجمع فساد المعاملة وفساد الاعتقاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص665-666.","url":""}]},{"id":"s14-56","number":56,"surah":14,"verses":[15],"verseLabel":"إبراهيم: 15","question":"لماذا نُكّر ﴿كُلُّ جَبَّارٍ عَنِيدٍ﴾؟","answer":"ليعم كل فرد بلغ أي صورة من هذين الوصفين، مع تحقير شأنه أمام قهر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص666.","url":""}]},{"id":"s14-57","number":57,"surah":14,"verses":[16],"verseLabel":"إبراهيم: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ وَرَائِهِ جَهَنَّمُ﴾؟","answer":"«من ورائه» تجعل جهنم مترصدة في مستقبل لا مهرب منه بعد خيبته في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص670.","url":""}]},{"id":"s14-58","number":58,"surah":14,"verses":[16],"verseLabel":"إبراهيم: 16","question":"لماذا بُني ﴿يُسْقَى﴾ للمفعول؟","answer":"لأن المقصود هول الشراب وإجبار المعذب عليه، لا تسمية الساقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص670.","url":""}]},{"id":"s14-59","number":59,"surah":14,"verses":[16],"verseLabel":"إبراهيم: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿مَاءٍ صَدِيدٍ﴾؟","answer":"جمع اللفظ بين ما يتوقع منه الري وما هو غاية القذر والألم، فكانت مفاجأة الصورة أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص671-672.","url":""}]},{"id":"s14-60","number":60,"surah":14,"verses":[17],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتَجَرَّعُهُ﴾؟","answer":"التفعل يصور ابتلاعه جرعة بعد جرعة بمشقة، لا شربًا طبيعيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص678.","url":""}]},{"id":"s14-61","number":61,"surah":14,"verses":[17],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكَانٍ﴾؟","answer":"استعارة تجعل أسباب الموت مهاجمة له من كل جهة، مع بقاء العذاب ومنع الراحة بالموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص678-680.","url":""}]},{"id":"s14-62","number":62,"surah":14,"verses":[17],"verseLabel":"إبراهيم: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا هُوَ بِمَيِّتٍ﴾ جملة اسمية مؤكدة بالباء؟","answer":"لترسيخ نفي الموت تمامًا مع تكرر أسبابه، فلا يجد نهاية للألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص680.","url":""}]},{"id":"s14-63","number":63,"surah":14,"verses":[17],"verseLabel":"إبراهيم: 17","question":"لماذا تكرر ﴿مِنْ وَرَائِهِ﴾؟","answer":"الأولى لجهنم وما فيها، والثانية لعذاب آخر متجدد؛ فكلما توهم نهاية وجد وراءها عذابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص682.","url":""}]},{"id":"s14-64","number":64,"surah":14,"verses":[17],"verseLabel":"إبراهيم: 17","question":"لماذا وصف العذاب بـ﴿غَلِيظٌ﴾؟","answer":"استعار الغلظ الحسي للشدة والثقل، ليجعل العذاب كشيء كثيف يحيط بصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص682.","url":""}]},{"id":"s14-65","number":65,"surah":14,"verses":[18],"verseLabel":"إبراهيم: 18","question":"لماذا شُبهت أعمال الكافرين بالرماد لا بالتراب؟","answer":"الرماد بقايا محترقة لا تماسك لها ولا نماء، فتجسد أعمالًا فقدت أصل القبول والنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص689-693.","url":""}]},{"id":"s14-66","number":66,"surah":14,"verses":[18],"verseLabel":"إبراهيم: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿اشْتَدَّتْ بِهِ الرِّيحُ﴾ بالإفراد؟","answer":"الريح المفردة تلائم مقام العقوبة والقوة المركزة التي تذر الرماد، بخلاف «الرياح» التي يكثر ورودها في الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص693.","url":""}]},{"id":"s14-67","number":67,"surah":14,"verses":[18],"verseLabel":"إبراهيم: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَقْدِرُونَ مِمَّا كَسَبُوا عَلَى شَيْءٍ﴾، وفي البقرة: ﴿لَا يَقْدِرُونَ عَلَى شَيْءٍ مِمَّا كَسَبُوا﴾؟","answer":"قُدّم ﴿مما كسبوا﴾ هنا لأن المثل مضروب لأعمالهم نفسها، فالكسب هو مركز الكلام.","sources":[{"label":"الكرماني، أسرار التكرار، ص154؛ الموسوعة ج24، ص695.","url":""}]},{"id":"s14-68","number":68,"surah":14,"verses":[18],"verseLabel":"إبراهيم: 18","question":"لماذا نُكرت ﴿شَيْءٍ﴾؟","answer":"للتحقير والاستغراق: لا يملكون أقل شيء من ثمرة أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص696.","url":""}]},{"id":"s14-69","number":69,"surah":14,"verses":[19],"verseLabel":"إبراهيم: 19","question":"ما سرّ تقديم السماوات على الأرض في الخلق؟","answer":"لأنها أعظم جرمًا وأسبق في مقام الاستدلال على القدرة المحيطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص703.","url":""}]},{"id":"s14-70","number":70,"surah":14,"verses":[19],"verseLabel":"إبراهيم: 19","question":"لماذا جُمعت السماوات وأُفردت الأرض؟","answer":"يشير الجمع إلى تعدد العوالم العلوية، والأرض إلى قرار البشر الواحد في هذا الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص703.","url":""}]},{"id":"s14-71","number":71,"surah":14,"verses":[19,20],"verseLabel":"إبراهيم: 19-20","question":"ما سرّ التعبير في قوله تعالى: ﴿يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ﴾ ثم ﴿وَمَا ذَلِكَ عَلَى اللَّهِ بِعَزِيزٍ﴾؟","answer":"ليحول دليل الخلق إلى تهديد مباشر بالاستبدال، ثم ينفي أي صعوبة عن وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص706-711.","url":""}]},{"id":"s14-72","number":72,"surah":14,"verses":[20],"verseLabel":"إبراهيم: 20","question":"ما سرّ تقديم ﴿عَلَى اللَّهِ﴾ على ﴿بِعَزِيزٍ﴾؟","answer":"لأن موضع العبرة أن الأمر لا يعجز الله خاصة، مهما بدا عظيمًا في حساب البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص711.","url":""}]},{"id":"s14-73","number":73,"surah":14,"verses":[21],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَرَزُوا لِلَّهِ جَمِيعًا﴾ بالماضي؟","answer":"لتحقيق وقوع القيامة حتى كأنها حدثت وشوهدت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص717.","url":""}]},{"id":"s14-74","number":74,"surah":14,"verses":[21],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قول الضعفاء: ﴿إِنَّا كُنَّا لَكُمْ تَبَعًا﴾ بالمصدر؟","answer":"«تبعًا» يجعل الاتباع وصفًا راسخًا وجماعيًا، لا أفعالًا متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص724.","url":""}]},{"id":"s14-75","number":75,"surah":14,"verses":[21],"verseLabel":"إبراهيم: 21","question":"ما سرّ تقديم قول الضعفاء قبل جواب المستكبرين؟","answer":"لإبراز أول صدمة في انهيار الولاء: الأتباع يطالبون قادتهم بما وعدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص721.","url":""}]},{"id":"s14-76","number":76,"surah":14,"verses":[21],"verseLabel":"إبراهيم: 21","question":"ما سرّ التعبير في قول المستكبرين: ﴿لَهَدَيْنَاكُمْ﴾ مع نسبة الهداية إلى أنفسهم؟","answer":"فضحًا لكذبهم وتملصهم؛ جعلوا هداية الله التي رفضوها أمرًا كان بأيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص731.","url":""}]},{"id":"s14-77","number":77,"surah":14,"verses":[21],"verseLabel":"إبراهيم: 21","question":"ما وجه قولهم: ﴿سَوَاءٌ عَلَيْنَا﴾ مع تقديم الخبر؟","answer":"لتقرير الاستواء واليأس قبل تفصيل حالتي الجزع والصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص732.","url":""}]},{"id":"s14-78","number":78,"surah":14,"verses":[22],"verseLabel":"إبراهيم: 22","question":"ما سرّ التعبير في قول الشيطان: ﴿لَمَّا قُضِيَ الْأَمْرُ﴾ بالبناء للمفعول؟","answer":"لأن المقام في حتم القضاء وانتهاء الاختيار، والفاعل معلوم لا يلتبس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص742-744.","url":""}]},{"id":"s14-79","number":79,"surah":14,"verses":[22],"verseLabel":"إبراهيم: 22","question":"لماذا فرّق بين ﴿وَعْدَ الْحَقِّ﴾ و﴿وَوَعَدْتُكُمْ فَأَخْلَفْتُكُمْ﴾؟","answer":"وعد الله حق ثابت، ووعد الشيطان خداع لا سلطان وراءه؛ والمقابلة تكشف مسؤولية من استجاب له.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص744-755.","url":""}]},{"id":"s14-80","number":80,"surah":14,"verses":[22],"verseLabel":"إبراهيم: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَلُومُونِي وَلُومُوا أَنْفُسَكُمْ﴾؟","answer":"ليعلن أن وسوسته لم تكن إكراهًا؛ فموضع اللوم اختيارهم الاستجابة بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص755-761.","url":""}]},{"id":"s14-81","number":81,"surah":14,"verses":[22],"verseLabel":"إبراهيم: 22","question":"ما سرّ تقديم ﴿مَا أَنَا بِمُصْرِخِكُمْ﴾ على ﴿وَمَا أَنْتُمْ بِمُصْرِخِيَّ﴾؟","answer":"بدأ بعجزه عن إنقاذهم لأنه ما تعلق به رجاؤهم، ثم نفى قدرتهم على إنقاذه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص761.","url":""}]},{"id":"s14-82","number":82,"surah":14,"verses":[22],"verseLabel":"إبراهيم: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ الظَّالِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ﴾؟","answer":"الجملة الاسمية والتوكيد وتقديم «لهم» تثبت اختصاصهم بالعذاب واستقراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص762-766.","url":""}]},{"id":"s14-83","number":83,"surah":14,"verses":[23],"verseLabel":"إبراهيم: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ﴾؟","answer":"تقديم الجار يصور الأنهار محيطة بأسفل الجنات ملازمة لها، فيكتمل مشهد النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص774.","url":""}]},{"id":"s14-84","number":84,"surah":14,"verses":[23],"verseLabel":"إبراهيم: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿بِإِذْنِ رَبِّهِمْ﴾؟","answer":"ليدل على أن الخلود نعمة مأذون بها من الرب المربي، لا خاصية مستقلة في الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص775.","url":""}]},{"id":"s14-85","number":85,"surah":14,"verses":[23],"verseLabel":"إبراهيم: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحِيَّتُهُمْ فِيهَا سَلَامٌ﴾ وقدّم ﴿فيها﴾؟","answer":"ليخص الجنة بهذا السلام الكامل الذي لا يعقبه أذى ولا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص776-777.","url":""}]},{"id":"s14-86","number":86,"surah":14,"verses":[24],"verseLabel":"إبراهيم: 24","question":"لماذا افتتح مثل الكلمة الطيبة بـ﴿أَلَمْ تَرَ كَيْفَ﴾؟","answer":"الاستفهام يوقظ للتأمل، و«كيف» توجه النظر إلى هيئة المثل وترابط أجزائه لا إلى مجرد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص784.","url":""}]},{"id":"s14-87","number":87,"surah":14,"verses":[24],"verseLabel":"إبراهيم: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿ضَرَبَ اللَّهُ مَثَلًا﴾ وذكر اسم الجلالة؟","answer":"للتفخيم والتنبيه إلى أن المثل صادر ممن أحاط بحقائق الأشياء، فلا يُتلقى كصورة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص785.","url":""}]},{"id":"s14-88","number":88,"surah":14,"verses":[24],"verseLabel":"إبراهيم: 24","question":"لماذا نُكرت ﴿كَلِمَةً﴾ ثم وُصفت بالطيبة؟","answer":"للتفخيم ثم البيان؛ كأن السامع ينتظر ماهية هذه الكلمة قبل أن يتلقى وصفها ومثلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص786.","url":""}]},{"id":"s14-89","number":89,"surah":14,"verses":[24],"verseLabel":"إبراهيم: 24","question":"لماذا شُبهت الكلمة الطيبة بشجرة لا بثَمرة؟","answer":"لأن الشجرة تجمع أصلًا ثابتًا ونموًا وفرعًا وثمرًا متجددًا؛ فتجسد الإيمان وآثاره المستمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص791-803.","url":""}]},{"id":"s14-90","number":90,"surah":14,"verses":[24],"verseLabel":"إبراهيم: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿أَصْلُهَا ثَابِتٌ وَفَرْعُهَا فِي السَّمَاءِ﴾؟","answer":"الثبات يصور رسوخ العقيدة، وعلو الفرع يصور رفعة العمل واتساع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص791-793.","url":""}]},{"id":"s14-91","number":91,"surah":14,"verses":[25],"verseLabel":"إبراهيم: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿تُؤْتِي أُكُلَهَا كُلَّ حِينٍ﴾ لا ثمرها؟","answer":"«الأكل» يبرز الثمرة من جهة نفعها وانتفاع الناس بها، وهو مقصد المثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص803.","url":""}]},{"id":"s14-92","number":92,"surah":14,"verses":[25],"verseLabel":"إبراهيم: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿بِإِذْنِ رَبِّهَا﴾؟","answer":"حتى الشجرة الطيبة لا تستقل بثمرها؛ فدوام النفع بتقدير ربها ورعايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص803؛ ج25، ص15.","url":""}]},{"id":"s14-93","number":93,"surah":14,"verses":[26],"verseLabel":"إبراهيم: 26","question":"لماذا شُبهت الكلمة الخبيثة بشجرة ﴿اجْتُثَّتْ﴾؟","answer":"الاجتثاث اقتلاع من الأصل؛ فالباطل قد يبدو قائمًا لكنه بلا جذر حق ولا بقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص15-17.","url":""}]},{"id":"s14-94","number":94,"surah":14,"verses":[26],"verseLabel":"إبراهيم: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا لَهَا مِنْ قَرَارٍ﴾؟","answer":"ينفي عنها أدنى ثبات مكاني أو معنوي، لتقابل رسوخ الشجرة الطيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص15-17.","url":""}]},{"id":"s14-95","number":95,"surah":14,"verses":[27],"verseLabel":"إبراهيم: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ﴾؟","answer":"جعل جزاء رسوخ كلمة الإيمان تثبيت أصحابها في الدنيا والآخرة؛ فناسب اللفظ المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص23-24.","url":""}]},{"id":"s14-96","number":96,"surah":14,"verses":[27],"verseLabel":"إبراهيم: 27","question":"ما سر الجناس بين ﴿يُثَبِّتُ﴾ و﴿الثَّابِتِ﴾؟","answer":"اشتُق وصف ﴿الثابت﴾ من مادة الفعل ﴿يثبت﴾؛ للإشارة إلى توفيق الله للمؤمنين وتثبيته إياهم بالقول الثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص24.","url":""}]},{"id":"s14-97","number":97,"surah":14,"verses":[28],"verseLabel":"إبراهيم: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿بَدَّلُوا نِعْمَتَ اللَّهِ كُفْرًا﴾؟","answer":"صوّر الكفر كبديل اختاروه مكان النعمة، ليظهر انقلاب العقل الذي قابل الهداية بالجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص29-34.","url":""}]},{"id":"s14-98","number":98,"surah":14,"verses":[29],"verseLabel":"إبراهيم: 29","question":"ما سرّ تقديم ﴿جَهَنَّمَ﴾ في ﴿جَهَنَّمَ يَصْلَوْنَهَا﴾؟","answer":"لتهويل المصير ومباغتة السامع باسمها قبل بيان دخولهم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص41.","url":""}]},{"id":"s14-99","number":99,"surah":14,"verses":[30],"verseLabel":"إبراهيم: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلُوا لِلَّهِ أَنْدَادًا﴾ وقدّم ﴿لله﴾؟","answer":"لتفظيع الجريمة: جعلوا الأنداد لمن ظهرت وحدانيته ونعمه، لا لشيء مجهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص46.","url":""}]},{"id":"s14-100","number":100,"surah":14,"verses":[31],"verseLabel":"إبراهيم: 31","question":"لماذا جاءت الأوامر: ﴿يُقِيمُوا الصَّلَاةَ وَيُنْفِقُوا﴾ بالمضارع؟","answer":"للدلالة على تجدد الإقامة والإنفاق واستمرارهما، لا أداء مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص55-56.","url":""}]},{"id":"s14-101","number":101,"surah":14,"verses":[31],"verseLabel":"إبراهيم: 31","question":"لماذا حُذفت لام الأمر قبل ﴿يُقِيمُوا﴾؟","answer":"جاء المضارع جوابًا للأمر ﴿قل﴾ بمعنى: قل لهم ليقيموا؛ فحذفت اللام تخفيفًا مع وضوح الطلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص56.","url":""}]},{"id":"s14-102","number":102,"surah":14,"verses":[31],"verseLabel":"إبراهيم: 31","question":"ما سرّ تقديم ﴿سِرًّا﴾ على ﴿عَلَانِيَةً﴾؟","answer":"لأن السر أقرب للإخلاص، ثم تُذكر العلانية حين تكون فيها قدوة ومصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص58.","url":""}]},{"id":"s14-103","number":103,"surah":14,"verses":[31],"verseLabel":"إبراهيم: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا بَيْعٌ فِيهِ وَلَا خِلَالٌ﴾؟","answer":"قابل إنفاق الدنيا الاختياري بيوم لا شراء فيه للنجاة ولا صداقة تنفع بغير إذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص58-62.","url":""}]},{"id":"s14-104","number":104,"surah":14,"verses":[32],"verseLabel":"إبراهيم: 32","question":"ما سرّ تقديم ﴿مِنَ السَّمَاءِ﴾ على ﴿مَاءً﴾؟","answer":"للفت النظر إلى جهة النعمة العلوية وإسناد إنزالها لله قبل ذكر مادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص66.","url":""}]},{"id":"s14-105","number":105,"surah":14,"verses":[32],"verseLabel":"إبراهيم: 32","question":"لماذا جُمعت وعُرّفت ﴿الثَّمَرَاتِ﴾؟","answer":"لاستحضار جنس الثمر كله بتنوعه وكثرته، لا ثمرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص67.","url":""}]},{"id":"s14-106","number":106,"surah":14,"verses":[32],"verseLabel":"إبراهيم: 32","question":"ما سرّ تقديم ﴿لَكُمُ﴾ على الفلك والأنهار؟","answer":"ليعجل الامتنان ويكرر إحساس المخاطب بأن هذه المخلوقات مسخرة لنفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص69-71.","url":""}]},{"id":"s14-107","number":107,"surah":14,"verses":[32],"verseLabel":"إبراهيم: 32","question":"لماذا جُمعت ﴿الأنهار﴾ وأُفردت ﴿الفلك﴾؟","answer":"«الفلك» اسم جنس يصدق على الواحد والجمع، أما الأنهار فجمعها يبرز تعدد المنافع والمجاري.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص69-72.","url":""}]},{"id":"s14-108","number":108,"surah":14,"verses":[33],"verseLabel":"إبراهيم: 33","question":"ما سرّ تقديم ﴿لَكُمُ﴾ قبل الشمس والقمر؟","answer":"لتكرار تقرير اختصاص الانتفاع وتسلسل النعم على الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص74.","url":""}]},{"id":"s14-109","number":109,"surah":14,"verses":[33],"verseLabel":"إبراهيم: 33","question":"لماذا جمع بين الشمس والقمر، والليل والنهار؟","answer":"جمع أزواج النظام الكوني المتقابلة ليدل على إحكام الزمن والرزق والحياة من جميع جهاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص74-76.","url":""}]},{"id":"s14-110","number":110,"surah":14,"verses":[33],"verseLabel":"إبراهيم: 33","question":"ما سرّ تقديم الليل على النهار؟","answer":"الليل يسبق النهار في الحساب الشرعي وفي إدراك السكون، ثم يأتي النهار للحركة والكسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص76.","url":""}]},{"id":"s14-111","number":111,"surah":14,"verses":[34],"verseLabel":"إبراهيم: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ كُلِّ مَا سَأَلْتُمُوهُ﴾؟","answer":"«من» تفيد أن ما أوتي البشر بعض خزائن الله، و«كل ما» يعم السؤال بلسان المقال والحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص80-82.","url":""}]},{"id":"s14-112","number":112,"surah":14,"verses":[34],"verseLabel":"إبراهيم: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ تَعُدُّوا نِعْمَتَ اللَّهِ﴾ بالإفراد؟","answer":"«نعمة» اسم جنس؛ وكل نعمة واحدة تنطوي على نعم لا تستقصى، فالإفراد أبلغ من الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص81-83.","url":""}]},{"id":"s14-113","number":113,"surah":14,"verses":[34],"verseLabel":"إبراهيم: 34","question":"لماذا ختم بـ﴿إِنَّ الْإِنْسَانَ لَظَلُومٌ كَفَّارٌ﴾؟","answer":"قابل فيض النعم بعجز الإنسان عن الإحصاء ثم بغلبة الظلم وكثرة كفران النعمة، ليدعوه إلى الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص83.","url":""}]},{"id":"s14-114","number":114,"surah":14,"verses":[35],"verseLabel":"إبراهيم: 35","question":"ما سرّ التعبير في قول إبراهيم: ﴿رَبِّ اجْعَلْ هَذَا الْبَلَدَ آمِنًا﴾، وفي البقرة: ﴿هَذَا بَلَدًا آمِنًا﴾؟","answer":"في البقرة دعا قبل استقرار مكة بلدًا، فنكّرها؛ وهنا دعا بعد صيرورتها البلد المعهود، فعرّفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص91-93؛ مسح عكسي.","url":""}]},{"id":"s14-115","number":115,"surah":14,"verses":[35],"verseLabel":"إبراهيم: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاجْنُبْنِي وَبَنِيَّ أَنْ نَعْبُدَ الْأَصْنَامَ﴾؟","answer":"«اجنبني» أبلغ من مجرد «امنعني»: طلب أن يجعل العبادة في جانب بعيد عنه وعن بنيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص94-100.","url":""}]},{"id":"s14-116","number":116,"surah":14,"verses":[36],"verseLabel":"إبراهيم: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي﴾؟","answer":"اختار «تبعني» لأن الانتساب الحقيقي لإبراهيم باتباع التوحيد، لا بمجرد النسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص101.","url":""}]},{"id":"s14-117","number":117,"surah":14,"verses":[36],"verseLabel":"إبراهيم: 36","question":"لماذا لم يقل: ومن عصاني فعاقبه؟","answer":"فوّض أمر العصاة إلى مغفرة الله ورحمته أدبًا ورجاءً، من غير أن يطلب لهم إقرارًا على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص101-108.","url":""}]},{"id":"s14-118","number":118,"surah":14,"verses":[37],"verseLabel":"إبراهيم: 37","question":"لماذا كرر إبراهيم ﴿رَبَّنَا﴾ وحذف أداة النداء؟","answer":"التكرار يجدد الافتقار عند كل مطلب، وحذف «يا» يشعر بالقرب وشدة المناجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص108-122.","url":""}]},{"id":"s14-119","number":119,"surah":14,"verses":[37],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿بِوَادٍ﴾ لا بمكان؟","answer":"الوادي يصور الانخفاض المحاط بالجبال وما فيه من الوحشة، فيظهر عظم التوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص110.","url":""}]},{"id":"s14-120","number":120,"surah":14,"verses":[37],"verseLabel":"إبراهيم: 37","question":"لماذا وصف البيت بـ﴿الْمُحَرَّمِ﴾ لا الحرام؟","answer":"اسم المفعول يشعر أن الله هو الذي جعله ذا حرمة ومنع انتهاكه، فتظهر عناية التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص112.","url":""}]},{"id":"s14-121","number":121,"surah":14,"verses":[37],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيُقِيمُوا الصَّلَاةَ﴾ فجعلها غاية الإسكان؟","answer":"اللام للتعليل؛ أي إن علة إسكانهم بهذا الوادي أن يقيموا الصلاة، فدلّ على أن العبادة هي مقصد الإسكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص112-122.","url":""}]},{"id":"s14-122","number":122,"surah":14,"verses":[37],"verseLabel":"إبراهيم: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاجْعَلْ أَفْئِدَةً مِنَ النَّاسِ تَهْوِي إِلَيْهِمْ﴾؟","answer":"اختار الأفئدة لأن الميل المقصود حب وشوق باطني، و«تهوي» تصور اندفاعًا عميقًا نحوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص112-122.","url":""}]},{"id":"s14-123","number":123,"surah":14,"verses":[38],"verseLabel":"إبراهيم: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ﴾؟","answer":"قدّم الخفي لأنه أدق وأبعد عن علم البشر؛ فمن علمه علم المعلن من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص123-125.","url":""}]},{"id":"s14-124","number":124,"surah":14,"verses":[38],"verseLabel":"إبراهيم: 38","question":"لماذا استعمل المضارع ﴿تَعْلَمُ﴾؟","answer":"للدلالة على دوام العلم وتجدد تعلقه بكل ما يخفى ويظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص123.","url":""}]},{"id":"s14-125","number":125,"surah":14,"verses":[39],"verseLabel":"إبراهيم: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهَبَ لِي عَلَى الْكِبَرِ﴾ لا أعطاني؟","answer":"الهبة عطاء بلا عوض ولا استحقاق، وذكر الكبر يظهر خرق العادة وتمام المنّة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص132.","url":""}]},{"id":"s14-126","number":126,"surah":14,"verses":[39],"verseLabel":"إبراهيم: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿إِسْمَاعِيلَ وَإِسْحَاقَ﴾ بهذا الترتيب؟","answer":"رتبهما بحسب الهبة والزمن؛ إسماعيل هو الابن الأكبر ثم إسحاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص132-138.","url":""}]},{"id":"s14-127","number":127,"surah":14,"verses":[40],"verseLabel":"إبراهيم: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ﴾ لا مصلّيًا؟","answer":"إقامة الصلاة أوسع من فعلها؛ تشمل دوامها وإتمام حدودها وآثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص138-140.","url":""}]},{"id":"s14-128","number":128,"surah":14,"verses":[40],"verseLabel":"إبراهيم: 40","question":"لماذا انتقل من ﴿رَبِّ﴾ المفرد إلى ﴿رَبَّنَا﴾ الجمع؟","answer":"بدأ بطلب يخصه وذريته، ثم أشرك المؤمنين في طلب قبول الدعاء تعميمًا للخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص138-139.","url":""}]},{"id":"s14-129","number":129,"surah":14,"verses":[40],"verseLabel":"إبراهيم: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَقَبَّلْ دُعَاءِ﴾ لا اقبل؟","answer":"صيغة التفعّل تفيد المبالغة في سؤال القبول والعناية بالدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص140.","url":""}]},{"id":"s14-130","number":130,"surah":14,"verses":[41],"verseLabel":"إبراهيم: 41","question":"لماذا جمع في الدعاء نفسه وأبويه والمؤمنين؟","answer":"تدرج من الأقرب إلى الأعم، ليجتمع حق النفس والوالدين وأخوة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص138-150.","url":""}]},{"id":"s14-131","number":131,"surah":14,"verses":[42],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْسَبَنَّ اللَّهَ غَافِلًا﴾ مع أن المؤمن لا يظن ذلك؟","answer":"النهي تثبيت للرسول ووعيد للظالمين؛ تأخر العقوبة ليس غفلة بل إمهال إلى يوم معلوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص150-152.","url":""}]},{"id":"s14-132","number":132,"surah":14,"verses":[42],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير بقوله تعالى: ﴿عَمَّا يَعْمَلُ الظَّالِمُونَ﴾ بالمضارع؟","answer":"ليصور ظلمهم المتجدد كله حاضرًا في العلم الإلهي لا يغيب منه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص150.","url":""}]},{"id":"s14-133","number":133,"surah":14,"verses":[42],"verseLabel":"إبراهيم: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿تَشْخَصُ فِيهِ الْأَبْصَارُ﴾؟","answer":"الشخوص ثبات العين مفتوحة بلا طرف من شدة الهول، وهي صورة أبلغ من مجرد النظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص150-161.","url":""}]},{"id":"s14-134","number":134,"surah":14,"verses":[43],"verseLabel":"إبراهيم: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿مُهْطِعِينَ مُقْنِعِي رُءُوسِهِمْ﴾؟","answer":"جمع سرعة الاندفاع مع رفع الرأس وتيبسه، فرسم أجسادًا مسلوبة الاختيار أمام الهول.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص161.","url":""}]},{"id":"s14-135","number":135,"surah":14,"verses":[43],"verseLabel":"إبراهيم: 43","question":"لماذا أُفرد ﴿طَرْفُهُمْ﴾ مع جمعهم؟","answer":"أفرد اسم الجنس لتشابه حال الأبصار كلها، كأن لهم طرفًا واحدًا لا يرتد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص161.","url":""}]},{"id":"s14-136","number":136,"surah":14,"verses":[43],"verseLabel":"إبراهيم: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَفْئِدَتُهُمْ هَوَاءٌ﴾ لا قلوبهم فارغة؟","answer":"الفؤاد موضع التوقد والإدراك، و«هواء» تشبيه بليغ يصور فراغه وذهاب تماسكه من الفزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص162-163.","url":""}]},{"id":"s14-137","number":137,"surah":14,"verses":[44],"verseLabel":"إبراهيم: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿يَوْمَ يَأْتِيهِمُ الْعَذَابُ﴾ لا يجيئهم؟","answer":"أُسند الإتيان إلى العذاب مجازًا بمعنى وقوعه عليهم؛ تهويلًا له وتفظيعًا، حتى كأنه يتحرك نحوهم بنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص171.","url":""}]},{"id":"s14-138","number":138,"surah":14,"verses":[44],"verseLabel":"إبراهيم: 44","question":"لماذا اقتصر على العذاب دون الثواب؟","answer":"لأن الخطاب إنذار للظالمين، فذكر ما يطابق المقام ويزلزل غفلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص171.","url":""}]},{"id":"s14-139","number":139,"surah":14,"verses":[44],"verseLabel":"إبراهيم: 44","question":"لماذا جاء: ﴿فَيَقُولُ الَّذِينَ ظَلَمُوا﴾ بالمضارع؟","answer":"لاستحضار توسّلهم المتأخر وكأنه يقع الآن أمام السامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص172.","url":""}]},{"id":"s14-140","number":140,"surah":14,"verses":[44],"verseLabel":"إبراهيم: 44","question":"لماذا وصف الأجل بـ﴿قَرِيبٍ﴾؟","answer":"القريب هنا بمعنى القليل؛ شُبّه قِصر الزمن بقرب المسافة، فهم يسألون مهلة قليلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص174.","url":""}]},{"id":"s14-141","number":141,"surah":14,"verses":[44],"verseLabel":"إبراهيم: 44","question":"ما وجه قولهم: ﴿نُجِبْ دَعْوَتَكَ وَنَتَّبِعِ الرُّسُلَ﴾؟","answer":"جمعوا أصل الاستجابة وتفصيلها العملي باتباع الرسل، اعترافًا بما كانوا يرفضونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص175.","url":""}]},{"id":"s14-142","number":142,"surah":14,"verses":[45],"verseLabel":"إبراهيم: 45","question":"ما سرّ التعبير بقوله تعالى: ﴿أَوَلَمْ تَكُونُوا أَقْسَمْتُمْ مِنْ قَبْلُ﴾؟","answer":"الاستفهام يوبخهم من داخل كلامهم القديم، و«تكونوا» يستحضر رسوخ حال القسم والتبجح.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص177-178.","url":""}]},{"id":"s14-143","number":143,"surah":14,"verses":[45],"verseLabel":"إبراهيم: 45","question":"ما وجه قولهم: ﴿مَا لَكُمْ مِنْ زَوَالٍ﴾ بالتنكير؟","answer":"لينفوا عن أنفسهم أي نوع أو قدر من الزوال، فجاء الرد أبلغ في كشف غرورهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص178-179.","url":""}]},{"id":"s14-144","number":144,"surah":14,"verses":[46],"verseLabel":"إبراهيم: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وَسَكَنْتُمْ فِي مَسَاكِنِ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ﴾؟","answer":"ليجعل الديار التي ورثوها شاهدًا محسوسًا؛ عرفوا المصير ثم كرروا سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص185.","url":""}]},{"id":"s14-145","number":145,"surah":14,"verses":[46],"verseLabel":"إبراهيم: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿وَضَرَبْنَا لَكُمُ الْأَمْثَالَ﴾ وقدّم ﴿لكم﴾؟","answer":"لإقامة الحجة عليهم خاصة: لم تكن الأمثال بعيدة، بل سيقت لمخاطبتهم وإنذارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص185.","url":""}]},{"id":"s14-146","number":146,"surah":14,"verses":[47],"verseLabel":"إبراهيم: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقَدْ مَكَرُوا مَكْرَهُمْ﴾؟","answer":"إضافة المكر إليهم تستوعب أقصى ما دبروه، ثم تضعه كله في علم الله وسلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص190-191.","url":""}]},{"id":"s14-147","number":147,"surah":14,"verses":[47],"verseLabel":"إبراهيم: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَ مَكْرُهُمْ لِتَزُولَ مِنْهُ الْجِبَالُ﴾؟","answer":"مبالغة تصوّر عظم تدبيرهم في ظنهم أو شناعته، مع أنه لا يخرج عن تقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص191-193.","url":""}]},{"id":"s14-148","number":148,"surah":14,"verses":[48],"verseLabel":"إبراهيم: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَحْسَبَنَّ اللَّهَ مُخْلِفَ وَعْدِهِ رُسُلَهُ﴾؟","answer":"أضاف الوعد إليه والرسل إليه ليجمع ضمان صدق الواعد وكرامة الموعودين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص193-205.","url":""}]},{"id":"s14-149","number":149,"surah":14,"verses":[48],"verseLabel":"إبراهيم: 48","question":"لماذا ختم بـ﴿عَزِيزٌ ذُو انْتِقَامٍ﴾؟","answer":"العزة تضمن القدرة على إنفاذ الوعد، والانتقام يطابق مقام أخذ المكذبين بعد الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص193-205.","url":""}]},{"id":"s14-150","number":150,"surah":14,"verses":[49],"verseLabel":"إبراهيم: 49","question":"ما سرّ تقديم تبديل الأرض على تبديل السماوات؟","answer":"قُدّم تبديل الأرض لقربها منا، ولأن تبديلها أعظم أثرًا بالنسبة إلينا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص205.","url":""}]},{"id":"s14-151","number":151,"surah":14,"verses":[49],"verseLabel":"إبراهيم: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾؟","answer":"الواحد يبطل كل شريك احتموا به، والقهار يزيل كل قوة توهموا أنها تمنعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص205-214.","url":""}]},{"id":"s14-152","number":152,"surah":14,"verses":[50],"verseLabel":"إبراهيم: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿وَتَرَى الْمُجْرِمِينَ﴾ بالمضارع؟","answer":"لاستحضار المشهد حتى يراه المخاطب رأي العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص214.","url":""}]},{"id":"s14-153","number":153,"surah":14,"verses":[50],"verseLabel":"إبراهيم: 50","question":"لماذا وصفهم بالمجرمين لا الظالمين؟","answer":"الإجرام يدل على قطع ما ينبغي وصله واكتساب الجناية، وهو أنسب عند ظهور أثر الجريمة والعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص215.","url":""}]},{"id":"s14-154","number":154,"surah":14,"verses":[50],"verseLabel":"إبراهيم: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿مُقَرَّنِينَ﴾ لا مقرونين؟","answer":"صيغة التفعيل تشعر بشدة الربط والتوثيق، وربط بعضهم ببعض أو بالشياطين والأغلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص215-216.","url":""}]},{"id":"s14-155","number":155,"surah":14,"verses":[50],"verseLabel":"إبراهيم: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي الْأَصْفَادِ﴾؟","answer":"«في» تجعل القيود كظرف يحيط بهم، فلا منفذ ولا حركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص216.","url":""}]},{"id":"s14-156","number":156,"surah":14,"verses":[51],"verseLabel":"إبراهيم: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿تَغْشَى وُجُوهَهُمُ النَّارُ﴾ بالمضارع؟","answer":"ليصور تجدد تغطية النار لأشرف مواضعهم وأشدها إحساسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص218.","url":""}]},{"id":"s14-157","number":157,"surah":14,"verses":[51],"verseLabel":"إبراهيم: 51","question":"ما سرّ تقديم ﴿وُجُوهَهُمُ﴾ على ﴿النار﴾؟","answer":"لأن الوجه أشرف ما في الإنسان، فذُكر وقُدّم تعجيلًا بإهانة المجرمين؛ وإهانته إهانة عظيمة لصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص219.","url":""}]},{"id":"s14-158","number":158,"surah":14,"verses":[51],"verseLabel":"إبراهيم: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيَجْزِيَ اللَّهُ كُلَّ نَفْسٍ مَا كَسَبَتْ﴾؟","answer":"عُبّر بأن الجزاء هو ما كسبته النفس، لا بأنه جزاء عملها؛ للإشارة إلى المساواة التامة بين العمل وجزائه، حتى كأن الجزاء هو العمل نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص219-227.","url":""}]},{"id":"s14-159","number":159,"surah":14,"verses":[52],"verseLabel":"إبراهيم: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿هَذَا بَلَاغٌ لِلنَّاسِ﴾ لا للمؤمنين؟","answer":"لأن القرآن حجة ورسالة عامة لكل الناس، وإن اختص أولو الألباب بكمال الاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص227-235.","url":""}]},{"id":"s14-160","number":160,"surah":14,"verses":[52],"verseLabel":"إبراهيم: 52","question":"ما سرّ تقديم ﴿وَلِيُنْذَرُوا بِهِ﴾ قبل العلم بالوحدانية والتذكر؟","answer":"الإنذار يوقظ القلب أولًا، ثم يثمر العلم بالتوحيد، ثم تتحول المعرفة إلى تذكر وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص235.","url":""}]},{"id":"s14-161","number":161,"surah":14,"verses":[52],"verseLabel":"إبراهيم: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِيَعْلَمُوا أَنَّمَا هُوَ إِلَهٌ وَاحِدٌ﴾؟","answer":"«أنما» تقصر الألوهية عليه، فجاء ختام السورة إلى الغاية التي دارت عليها حججها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص227-235.","url":""}]},{"id":"s14-162","number":162,"surah":14,"verses":[52],"verseLabel":"إبراهيم: 52","question":"لماذا خُتمت السورة بـ﴿وَلِيَذَّكَّرَ أُولُو الْأَلْبَابِ﴾؟","answer":"لأن البلاغ والإنذار والحجج لا تبلغ غايتها إلا في عقل خالص ينقل المعرفة إلى اتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص227-235.","url":""}]},{"id":"s15-1","number":1,"surah":15,"verses":[1],"verseLabel":"الحجر: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ الْكِتَابِ وَقُرْآنٍ مُبِينٍ﴾؟","answer":"جمع بين كونها آيات مكتوبة محفوظة وقرآنًا مقروءًا ظاهر الدلالة، فاستوعب وجهي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص263-265.","url":""}]},{"id":"s15-2","number":2,"surah":15,"verses":[1],"verseLabel":"الحجر: 1","question":"لماذا أُضيفت ﴿آيَاتُ﴾ إلى ﴿الْكِتَابِ﴾؟","answer":"للدلالة على أن كل آية جزء محكم من كتاب جامع، وليست كلمات متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص263.","url":""}]},{"id":"s15-3","number":3,"surah":15,"verses":[1],"verseLabel":"الحجر: 1","question":"لماذا أخّر وصف ﴿وَقُرْآنٍ مُبِينٍ﴾؟","answer":"أُخّر وصف القرآنية لأنه أدخل في المدح وأرسخ في التعريف بهذا الوحي، بعد التنبيه أولًا على اشتماله على كمالات الكتب الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص264.","url":""}]},{"id":"s15-4","number":4,"surah":15,"verses":[1],"verseLabel":"الحجر: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿مُبِينٍ﴾ وحذف ما يبينه؟","answer":"ليعم: مبين في نفسه، ومبين للحق والهدى والأحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص265.","url":""}]},{"id":"s15-5","number":5,"surah":15,"verses":[2],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿رُبَمَا يَوَدُّ الَّذِينَ كَفَرُوا﴾ مع أن الندم محقق؟","answer":"«ربما» تحكي تكرر لحظات التمني كلما انكشف لهم فضل الإسلام، لا التشكيك في وقوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص269-270.","url":""}]},{"id":"s15-6","number":6,"surah":15,"verses":[2],"verseLabel":"الحجر: 2","question":"لماذا جاء ﴿يَوَدُّ﴾ بالمضارع؟","answer":"لاستحضار الندم متجددًا أمام السامع وكأنه يقع الآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص269.","url":""}]},{"id":"s15-7","number":7,"surah":15,"verses":[2],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿الَّذِينَ كَفَرُوا﴾ لا الكافرون؟","answer":"الصلة تستحضر فعلهم الاختياري الذي أفضى إلى الندم، لا مجرد لقب ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص270.","url":""}]},{"id":"s15-8","number":8,"surah":15,"verses":[2],"verseLabel":"الحجر: 2","question":"لماذا حُذف متعلق الكفر؟","answer":"ليعم كفرهم بالله والرسول والقرآن والبعث، حتى صار الكفر سمتهم الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص270.","url":""}]},{"id":"s15-9","number":9,"surah":15,"verses":[2],"verseLabel":"الحجر: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لَوْ كَانُوا مُسْلِمِينَ﴾ بصيغة الغيبة؟","answer":"لإبعادهم عن مقام الخطاب إهانة، وتصويرهم كغائبين ينظر إلى مصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص271.","url":""}]},{"id":"s15-10","number":10,"surah":15,"verses":[3],"verseLabel":"الحجر: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿ذَرْهُمْ يَأْكُلُوا وَيَتَمَتَّعُوا﴾؟","answer":"أمر تهديد لا إباحة؛ يحقر غايتهم حين اختزلوا حياتهم في الأكل والمتاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص274-276.","url":""}]},{"id":"s15-11","number":11,"surah":15,"verses":[3],"verseLabel":"الحجر: 3","question":"ما سرّ تقديم الضمير في ﴿وَيُلْهِهِمُ الْأَمَلُ﴾؟","answer":"لتعيينهم هدفًا لهذا الإلهاء، وكأن الأمل استولى عليهم خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص277.","url":""}]},{"id":"s15-12","number":12,"surah":15,"verses":[3],"verseLabel":"الحجر: 3","question":"لماذا حُذف ما يلهيهم عنه الأمل؟","answer":"ليعم كل ما صرفهم عنه: الإيمان والتوبة والاستعداد للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص277.","url":""}]},{"id":"s15-13","number":13,"surah":15,"verses":[3],"verseLabel":"الحجر: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَوْفَ يَعْلَمُونَ﴾ ولم يذكر ما يعلمون؟","answer":"التهديد أبلغ حين يترك الهول غير محدود، ليعلموا حقيقة العاقبة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص278-279.","url":""}]},{"id":"s15-14","number":14,"surah":15,"verses":[4],"verseLabel":"الحجر: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا أَهْلَكْنَا مِنْ قَرْيَةٍ﴾ لا من أهل قرية؟","answer":"أقام المكان مقام أهله ليصور الاستئصال وقد شمل المجتمع والعمران الذي احتموا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص282-284.","url":""}]},{"id":"s15-15","number":15,"surah":15,"verses":[4],"verseLabel":"الحجر: 4","question":"لماذا نُكرت ﴿قَرْيَةٍ﴾ في سياق النفي؟","answer":"لتعم كل قرية بلا استثناء، فلا يقع الهلاك خارج السنة المقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص283.","url":""}]},{"id":"s15-16","number":16,"surah":15,"verses":[4],"verseLabel":"الحجر: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿لَهَا كِتَابٌ مَعْلُومٌ﴾؟","answer":"صوّر الأجل سجلًا مقدرًا مضبوطًا، فلا عشوائية في الإمهال ولا الإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص287.","url":""}]},{"id":"s15-17","number":17,"surah":15,"verses":[5],"verseLabel":"الحجر: 5","question":"لماذا أُسند الأجل إلى ﴿أُمَّةٍ﴾ لا إلى القرية؟","answer":"لأن المسؤولية والتكليف والهلاك تتعلق بالجماعة البشرية، أما القرية فوعاؤها المكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص289.","url":""}]},{"id":"s15-18","number":18,"surah":15,"verses":[5],"verseLabel":"الحجر: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَسْبِقُ... وَمَا يَسْتَأْخِرُونَ﴾ بالمضارع؟","answer":"لتقرير سنة مطردة تتكرر في كل أمة وفي كل أجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص290.","url":""}]},{"id":"s15-19","number":19,"surah":15,"verses":[5],"verseLabel":"الحجر: 5","question":"لماذا استعمل ﴿يَسْتَأْخِرُونَ﴾ بصيغة الاستفعال؟","answer":"للمبالغة في نفي قدرتهم حتى على طلب التأخر أو تحصيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص290-291.","url":""}]},{"id":"s15-20","number":20,"surah":15,"verses":[6],"verseLabel":"الحجر: 6","question":"ما وجه قولهم ساخرين: ﴿يَا أَيُّهَا الَّذِي نُزِّلَ عَلَيْهِ الذِّكْرُ﴾؟","answer":"حكوا وصفه بما يزعمه هو تهكمًا، فجاء الرد بتثبيت حقيقة التنزيل وحفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص295-297.","url":""}]},{"id":"s15-21","number":21,"surah":15,"verses":[6],"verseLabel":"الحجر: 6","question":"ما سرّ اختيارهم البناء للمفعول في قولهم: ﴿نُزِّلَ عَلَيْهِ﴾؟","answer":"تعمدوا إبهام المنزِّل مع جحودهم، بينما السياق يعيد الأمر إلى الله صراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص296.","url":""}]},{"id":"s15-22","number":22,"surah":15,"verses":[6],"verseLabel":"الحجر: 6","question":"لماذا سُمّي القرآن ﴿الذِّكْرَ﴾؟","answer":"لأنه يذكّر بالفطرة والحق والعاقبة، ويبقى ذكرًا محفوظًا متجدد التلاوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص297.","url":""}]},{"id":"s15-23","number":23,"surah":15,"verses":[6],"verseLabel":"الحجر: 6","question":"ما وجه قولهم: ﴿إِنَّكَ لَمَجْنُونٌ﴾ بمؤكدين؟","answer":"لإظهار بلوغ العناد مبلغ الجزم بالباطل رغم ظهور صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص297-298.","url":""}]},{"id":"s15-24","number":24,"surah":15,"verses":[7],"verseLabel":"الحجر: 7","question":"لماذا طلبوا الملائكة بدل آية أخرى؟","answer":"زعموا أن تصديق الرسول يحتاج شاهدًا ملكيًا، مع أن نزول الملائكة على وجههم يكون بالعذاب لا الاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص301-302.","url":""}]},{"id":"s15-25","number":25,"surah":15,"verses":[7],"verseLabel":"الحجر: 7","question":"ما وجه قولهم: ﴿إِنْ كُنْتَ مِنَ الصَّادِقِينَ﴾ مع حذف المتعلق؟","answer":"ليعم صدقه في دعوى الرسالة والوحي والوعيد الذي أنذرهم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص302.","url":""}]},{"id":"s15-26","number":26,"surah":15,"verses":[8],"verseLabel":"الحجر: 8","question":"لماذا جاء الجواب: ﴿مَا نُنَزِّلُ الْمَلَائِكَةَ إِلَّا بِالْحَقِّ﴾؟","answer":"عدل عن مجاراة اقتراحهم إلى بيان السنة: تنزل الملائكة لحكمة وحكم نافذ، لا للعبث والتعنت.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص306-307.","url":""}]},{"id":"s15-27","number":27,"surah":15,"verses":[8],"verseLabel":"الحجر: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿بِالْحَقِّ﴾؟","answer":"الباء تصاحب التنزيل بالغاية والحكمة؛ فإذا نزلوا بالعذاب انتهى زمن الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص307.","url":""}]},{"id":"s15-28","number":28,"surah":15,"verses":[8],"verseLabel":"الحجر: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا كَانُوا إِذًا مُنْظَرِينَ﴾؟","answer":"«إذًا» تربط تحقق اقتراحهم بزوال المهلة فورًا، فتقلب طلبهم حجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص309-311.","url":""}]},{"id":"s15-29","number":29,"surah":15,"verses":[9],"verseLabel":"الحجر: 9","question":"لماذا توالت المؤكدات في ﴿إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ﴾؟","answer":"لرد إنكارهم واستهزائهم بأقوى تقرير: المنزّل هو الله نفسه لا مدخل لبشر في مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص314-315.","url":""}]},{"id":"s15-30","number":30,"surah":15,"verses":[9],"verseLabel":"الحجر: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿نَزَّلْنَا﴾ لا أنزلنا؟","answer":"التفعيل يلائم تنزيله مفرقًا متدرجًا بحسب الوقائع، مع تكرر العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص314.","url":""}]},{"id":"s15-31","number":31,"surah":15,"verses":[9],"verseLabel":"الحجر: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّا لَهُ لَحَافِظُونَ﴾ جملة اسمية؟","answer":"لإفادة الثبات والدوام، لا حفظًا مؤقتًا ينتهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص315-317.","url":""}]},{"id":"s15-32","number":32,"surah":15,"verses":[9],"verseLabel":"الحجر: 9","question":"ما سرّ تقديم ﴿لَهُ﴾ على ﴿لَحَافِظُونَ﴾؟","answer":"للاختصاص والاهتمام: هذا الذكر محفوظ بعناية خاصة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص316.","url":""}]},{"id":"s15-33","number":33,"surah":15,"verses":[9],"verseLabel":"الحجر: 9","question":"لماذا حُذف ما يُحفظ منه القرآن؟","answer":"ليعم الحفظ من التبديل والزيادة والنقص والضياع والتناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص317.","url":""}]},{"id":"s15-34","number":34,"surah":15,"verses":[10],"verseLabel":"الحجر: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَقَدْ أَرْسَلْنَا مِنْ قَبْلِكَ﴾؟","answer":"المؤكدات تسلي النبي بأن الاستهزاء سنة قديمة، وأنه ليس أول رسول يواجهها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص319.","url":""}]},{"id":"s15-35","number":35,"surah":15,"verses":[10],"verseLabel":"الحجر: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي شِيَعِ الْأَوَّلِينَ﴾؟","answer":"«الشيع» جماعات يجمعها مذهب وهوى؛ فصورت تكرر الرسالة بين أمم متفرقة متحزبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص320-321.","url":""}]},{"id":"s15-36","number":36,"surah":15,"verses":[11],"verseLabel":"الحجر: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا يَأْتِيهِمْ مِنْ رَسُولٍ﴾؟","answer":"«من» تؤكد الاستغراق: ما جاءهم رسول قط إلا قابلوه بالنمط نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص323.","url":""}]},{"id":"s15-37","number":37,"surah":15,"verses":[11],"verseLabel":"الحجر: 11","question":"ما سرّ تقديم ﴿بِهِ﴾ في ﴿كَانُوا بِهِ يَسْتَهْزِئُونَ﴾؟","answer":"لتوجيه الإنكار إلى الرسول والحق الذي كان ينبغي تعظيمه، فإذا به موضع سخريتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص323-324.","url":""}]},{"id":"s15-38","number":38,"surah":15,"verses":[12],"verseLabel":"الحجر: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ﴾؟","answer":"السلك إدخال الشيء في مسلك دقيق؛ فصوّر وصول الذكر أو التكذيب إلى أعماق قلوبهم مع إصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص330.","url":""}]},{"id":"s15-39","number":39,"surah":15,"verses":[12],"verseLabel":"الحجر: 12","question":"لماذا سُمّوا ﴿الْمُجْرِمِينَ﴾؟","answer":"لأنهم قطعوا صلتهم بالحق باختيارهم، فالإجرام يبين سبب عدم الانتفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص332.","url":""}]},{"id":"s15-40","number":40,"surah":15,"verses":[13],"verseLabel":"الحجر: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يُؤْمِنُونَ بِهِ﴾ بالمضارع؟","answer":"ليصور استمرار موقفهم رغم تجدد الآيات والحجج.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص333.","url":""}]},{"id":"s15-41","number":41,"surah":15,"verses":[14],"verseLabel":"الحجر: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَوْ فَتَحْنَا عَلَيْهِمْ بَابًا مِنَ السَّمَاءِ﴾؟","answer":"أقصى المشهد إلى معاينة باب السماء ليبين أن المشكلة ليست نقص الدليل بل فساد التلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص337-338.","url":""}]},{"id":"s15-42","number":42,"surah":15,"verses":[14],"verseLabel":"الحجر: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿فَظَلُّوا فِيهِ يَعْرُجُونَ﴾؟","answer":"«ظلوا» تفيد الاستمرار نهارًا، و«يعرجون» يصور صعودًا متكررًا لا لمحة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص338-339.","url":""}]},{"id":"s15-43","number":43,"surah":15,"verses":[15],"verseLabel":"الحجر: 15","question":"ما وجه قولهم: ﴿إِنَّمَا سُكِّرَتْ أَبْصَارُنَا﴾؟","answer":"حصروا المعاينة في تعطيل البصر تهربًا من الإيمان، ثم تجاوزوا الحس إلى اتهام السحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص341-342.","url":""}]},{"id":"s15-44","number":44,"surah":15,"verses":[15],"verseLabel":"الحجر: 15","question":"لماذا انتقلوا من ﴿سُكِّرَتْ أَبْصَارُنَا﴾ إلى ﴿قَوْمٌ مَسْحُورُونَ﴾؟","answer":"لأنهم حين لم يكف إنكار العين اتهموا الذات كلها بالسحر، فتكشف الآية تدرج المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص341-342.","url":""}]},{"id":"s15-45","number":45,"surah":15,"verses":[16],"verseLabel":"الحجر: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلْنَا فِي السَّمَاءِ بُرُوجًا﴾؟","answer":"«جعل» يبرز وضعها المنظم بوظائفها ومنازلها، لا مجرد إيجاد مادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص344-347.","url":""}]},{"id":"s15-46","number":46,"surah":15,"verses":[16],"verseLabel":"الحجر: 16","question":"ما سرّ تقديم ﴿فِي السَّمَاءِ﴾ على ﴿بُرُوجًا﴾؟","answer":"لتوجيه النظر أولًا إلى صفحة السماء ثم ما وُضع فيها من علامات وزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص347.","url":""}]},{"id":"s15-47","number":47,"surah":15,"verses":[16],"verseLabel":"الحجر: 16","question":"لماذا حُذف متعلق ﴿وَزَيَّنَّاهَا﴾؟","answer":"ليعم الزينة بالنجوم والبروج والهيئة والنظام وكل ما يبهج الناظرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص349.","url":""}]},{"id":"s15-48","number":48,"surah":15,"verses":[18],"verseLabel":"الحجر: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿اسْتَرَقَ السَّمْعَ﴾؟","answer":"الافتعال يصور تكلف الخطف في خفاء، لا سماعًا مشروعًا متمكنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص358.","url":""}]},{"id":"s15-49","number":49,"surah":15,"verses":[19],"verseLabel":"الحجر: 19","question":"لماذا وصل خلق الأرض بما قبله بالواو؟","answer":"لجمع دلائل العالم العلوي والسفلي في مشهد قدرة واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص362.","url":""}]},{"id":"s15-50","number":50,"surah":15,"verses":[19],"verseLabel":"الحجر: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَلْقَيْنَا فِيهَا رَوَاسِيَ﴾؟","answer":"الإلقاء يصور التثبيت القوي للجبال، والرواسي تستحضر وظيفتها في قرار الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص362-364.","url":""}]},{"id":"s15-51","number":51,"surah":15,"verses":[19],"verseLabel":"الحجر: 19","question":"ما سرّ تقديم ﴿فِيهَا﴾؟","answer":"لإبراز الأرض وعاءً جامعًا للرواسي والنبات الموزون، فتترابط النعم في موطن الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص364.","url":""}]},{"id":"s15-52","number":52,"surah":15,"verses":[20],"verseLabel":"الحجر: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وَجَعَلْنَا لَكُمْ فِيهَا مَعَايِشَ﴾ وقدّم ﴿لكم﴾؟","answer":"لتعجيل الامتنان وإشعار الإنسان بأن نظام الأرض مهيأ لمعيشته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص369.","url":""}]},{"id":"s15-53","number":53,"surah":15,"verses":[20],"verseLabel":"الحجر: 20","question":"من المقصود بـ﴿وَمَنْ لَسْتُمْ لَهُ بِرَازِقِينَ﴾؟","answer":"يشمل العيال والدواب والخدم وسائر من ينتفع؛ أنتم أسباب ظاهرية ورزق الجميع على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص372.","url":""}]},{"id":"s15-54","number":54,"surah":15,"verses":[21],"verseLabel":"الحجر: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ مِنْ شَيْءٍ إِلَّا عِنْدَنَا خَزَائِنُهُ﴾؟","answer":"نفي واستثناء يفيدان الحصر: أصول النعم ومقاديرها كلها بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص376.","url":""}]},{"id":"s15-55","number":55,"surah":15,"verses":[21],"verseLabel":"الحجر: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا نُنَزِّلُهُ إِلَّا بِقَدَرٍ مَعْلُومٍ﴾؟","answer":"صوّر الإمداد إنزالًا من خزائن، لكنه موزون بالحكمة لا وفق استعجال البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص379.","url":""}]},{"id":"s15-56","number":56,"surah":15,"verses":[22],"verseLabel":"الحجر: 22","question":"لماذا وصف الرياح بـ﴿لَوَاقِحَ﴾؟","answer":"يجمع تلقيح السحاب والنبات، في كلمة تصور الريح سببًا خفيًا للحياة والرزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص386-390.","url":""}]},{"id":"s15-57","number":57,"surah":15,"verses":[22],"verseLabel":"الحجر: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَسْقَيْنَاكُمُوهُ﴾ بهذه الصيغة الطويلة؟","answer":"جمعت الإنزال والتوصيل والتمكين من الشرب في لفظ واحد، وألصقت النعمة بالمخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص388-390.","url":""}]},{"id":"s15-58","number":58,"surah":15,"verses":[23],"verseLabel":"الحجر: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّا لَنَحْنُ نُحْيِي وَنُمِيتُ﴾؟","answer":"تتابع المؤكدات يقصر الإحياء والإماتة الحقيقيين على الله، ردًا على كل وهم بالاستقلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص394-395.","url":""}]},{"id":"s15-59","number":59,"surah":15,"verses":[23],"verseLabel":"الحجر: 23","question":"لماذا حُذف مفعولا ﴿نُحْيِي وَنُمِيتُ﴾؟","answer":"ليعم كل حي وكل ميت وفي كل صورة وزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص395.","url":""}]},{"id":"s15-60","number":60,"surah":15,"verses":[24],"verseLabel":"الحجر: 24","question":"لماذا كرر العلم بالمستقدمين والمستأخرين؟","answer":"ليستوعب من مضى ومن يأتي، ومن تقدم في الطاعة أو تأخر، فلا يغيب فرد عن الحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص402.","url":""}]},{"id":"s15-61","number":61,"surah":15,"verses":[25],"verseLabel":"الحجر: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ رَبَّكَ هُوَ يَحْشُرُهُمْ﴾؟","answer":"أكّد الخبر بـ﴿إنَّ﴾ وضمير الفصل ﴿هو﴾؛ لإفادة اختصاص الله بالحشر وتوكيد وقوعه، فلا يقدر عليه غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص407.","url":""}]},{"id":"s15-62","number":62,"surah":15,"verses":[25],"verseLabel":"الحجر: 25","question":"لماذا ختم بـ﴿حَكِيمٌ عَلِيمٌ﴾ بهذا الترتيب؟","answer":"الحكمة تفسر تقدير الخلق والحشر، والعلم يضمن إحاطة الحساب بكل فرد وعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص408.","url":""}]},{"id":"s15-63","number":63,"surah":15,"verses":[26,27],"verseLabel":"الحجر: 26-27","question":"لماذا فصّل أصل الإنسان وأصل الجان؟","answer":"ليُظهر اختلاف المادتين مع وحدة الخالق، ويمهد لفتنة الكبر التي تعلقت بالمادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص421-425.","url":""}]},{"id":"s15-64","number":64,"surah":15,"verses":[29],"verseLabel":"الحجر: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿فَقَعُوا لَهُ سَاجِدِينَ﴾ لا اسجدوا فقط؟","answer":"«فقعوا» تصور سرعة الهوي الكامل فور تمام خلقه ونفخ الروح فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص425-439.","url":""}]},{"id":"s15-65","number":65,"surah":15,"verses":[30],"verseLabel":"الحجر: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَجَدَ الْمَلَائِكَةُ كُلُّهُمْ أَجْمَعُونَ﴾ وجمع مؤكدين؟","answer":"«كلهم» ينفي تخلف فرد، و«أجمعون» ينفي تفرق الوقت؛ فتم الامتثال كاملًا فورًا.","sources":[{"label":"الكرماني، أسرار التكرار، ص155؛ الموسوعة ج25، ص437-439.","url":""}]},{"id":"s15-66","number":66,"surah":15,"verses":[32],"verseLabel":"الحجر: 32","question":"لماذا جاء الاستفهام: ﴿مَا لَكَ أَلَّا تَكُونَ مَعَ السَّاجِدِينَ﴾؟","answer":"ليس طلب علم، بل كشف لعلة التمرد وتوبيخ على الانفصال عن الجماعة المطيعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص438-439.","url":""}]},{"id":"s15-67","number":67,"surah":15,"verses":[33],"verseLabel":"الحجر: 33","question":"ما سرّ التعبير في قول إبليس: ﴿لَمْ أَكُنْ لِأَسْجُدَ﴾؟","answer":"اللام تفيد شدة الامتناع وزعمه أن السجود لا يليق به أصلًا، ففضحت كبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص442-443.","url":""}]},{"id":"s15-68","number":68,"surah":15,"verses":[34],"verseLabel":"الحجر: 34","question":"لماذا جاء: ﴿فَاخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ﴾ بالفاء؟","answer":"الفاء تجعل الطرد نتيجة عاجلة مباشرة للكبر والعصيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص447-449.","url":""}]},{"id":"s15-69","number":69,"surah":15,"verses":[34],"verseLabel":"الحجر: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿رَجِيمٌ﴾ لا مطرود؟","answer":"الرجيم يجمع الطرد والإبعاد والرجم واللعن، فهو أبلغ في الإهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص448-449.","url":""}]},{"id":"s15-70","number":70,"surah":15,"verses":[35],"verseLabel":"الحجر: 35","question":"ما سرّ تقديم ﴿عَلَيْكَ﴾؟","answer":"للاختصاص والتعجيل بإلصاق اللعنة به جزاء تمرده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص451-452.","url":""}]},{"id":"s15-71","number":71,"surah":15,"verses":[36],"verseLabel":"الحجر: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَى يَوْمِ يُبْعَثُونَ﴾؟","answer":"طلب البقاء إلى نهاية حياة البشر ليغويهم طوال زمن التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص458-460.","url":""}]},{"id":"s15-72","number":72,"surah":15,"verses":[37,38],"verseLabel":"الحجر: 37-38","question":"ما سرّ التعبير بقوله تعالى: ﴿مِنَ الْمُنْظَرِينَ إِلَى يَوْمِ الْوَقْتِ الْمَعْلُومِ﴾؟","answer":"لم يُعط ما طلب على إطلاقه، بل أُدخل في جملة من أمهلوا إلى حد معلوم عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص461-462.","url":""}]},{"id":"s15-73","number":73,"surah":15,"verses":[39],"verseLabel":"الحجر: 39","question":"ما سرّ التعبير في قول إبليس: ﴿بِمَا أَغْوَيْتَنِي﴾؟","answer":"التعبير بالإغواء يشعر بانغماس إبليس في الباطل وفساده فسادًا لا يُرجى معه صلاحه؛ وفيه تنبيه لبني آدم من وسوسته، إذ لا يرى سوى الباطل ولا يأمر إلا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص469-470.","url":""}]},{"id":"s15-74","number":74,"surah":15,"verses":[39],"verseLabel":"الحجر: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿لَأُزَيِّنَنَّ لَهُمْ فِي الْأَرْضِ﴾؟","answer":"المراد أنه يزيّن لبني آدم الباطل والمعاصي فيحببها إليهم، و﴿في الأرض﴾ تقيد ذلك بزمن وجودهم في الدنيا، دار متاعهم وابتلائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص469-472.","url":""}]},{"id":"s15-75","number":75,"surah":15,"verses":[39],"verseLabel":"الحجر: 39","question":"ما سرّ إسناد الإغواء إلى إبليس في قوله: ﴿وَلَأُغْوِيَنَّهُمْ أَجْمَعِينَ﴾؟","answer":"الإسناد مجاز عقلي؛ أي لأحملنهم على الغواية وأتسبب فيها، وفيه تصوير شدة حرص إبليس واجتهاده في إضلال بني آدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص470.","url":""}]},{"id":"s15-76","number":76,"surah":15,"verses":[40],"verseLabel":"الحجر: 40","question":"لماذا استثنى ﴿عِبَادَكَ مِنْهُمُ الْمُخْلَصِينَ﴾؟","answer":"يعترف أن سلطان التزيين ينكسر أمام من أخلصهم الله وحفظ توحيدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص473-475.","url":""}]},{"id":"s15-77","number":77,"surah":15,"verses":[40],"verseLabel":"الحجر: 40","question":"ما سرّ تقديم ﴿مِنْهُمْ﴾؟","answer":"لإبراز أن المخلصين خارجون من قلب الجماعة المستهدفة، لا عالم منفصل عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص474.","url":""}]},{"id":"s15-78","number":78,"surah":15,"verses":[41],"verseLabel":"الحجر: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿هَذَا صِرَاطٌ عَلَيَّ مُسْتَقِيمٌ﴾؟","answer":"إشارة إلى سنة محققة ملتزمة بحكمته: طريق العبودية الخالصة مستقيم موصل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص478-479.","url":""}]},{"id":"s15-79","number":79,"surah":15,"verses":[42],"verseLabel":"الحجر: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ﴾؟","answer":"أكد النسبة إليه تشريفًا وحفظًا، ونفى عن إبليس الحجة والقهر، لا مجرد الوسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص483-486.","url":""}]},{"id":"s15-80","number":80,"surah":15,"verses":[42],"verseLabel":"الحجر: 42","question":"ما سرّ تقديم ﴿لَكَ عَلَيْهِمْ﴾ على ﴿سُلْطَانٌ﴾؟","answer":"للتشديد على نفي السلطان عنه خاصة على عباد الله خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص484-486.","url":""}]},{"id":"s15-81","number":81,"surah":15,"verses":[42],"verseLabel":"الحجر: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا مَنِ اتَّبَعَكَ﴾ لا من أغويته؟","answer":"أثبت مسؤولية الإنسان؛ إبليس يدعو، والغاوي هو الذي يختار اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص488.","url":""}]},{"id":"s15-82","number":82,"surah":15,"verses":[43],"verseLabel":"الحجر: 43","question":"لماذا سميت جهنم ﴿مَوْعِدَهُمْ﴾؟","answer":"لأنها نهاية موعودون بها لا يخطئونها، فجمع اللفظ بين الزمان والمكان المحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص491-492.","url":""}]},{"id":"s15-83","number":83,"surah":15,"verses":[44],"verseLabel":"الحجر: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿لَهَا سَبْعَةُ أَبْوَابٍ﴾؟","answer":"تعدد الأبواب يصور إحكامها وتوزع الداخلين بحسب أصناف الغواية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص496-499.","url":""}]},{"id":"s15-84","number":84,"surah":15,"verses":[44],"verseLabel":"الحجر: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿لِكُلِّ بَابٍ مِنْهُمْ جُزْءٌ مَقْسُومٌ﴾؟","answer":"يفيد أن الدخول ليس فوضى؛ لكل صنف نصيب محدد محسوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص497-499.","url":""}]},{"id":"s15-85","number":85,"surah":15,"verses":[45],"verseLabel":"الحجر: 45","question":"لماذا حُذف متعلق التقوى في ﴿الْمُتَّقِينَ﴾؟","answer":"ليعم اتقاء الشرك والمعاصي وكل ما يبعد عن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص501.","url":""}]},{"id":"s15-86","number":86,"surah":15,"verses":[45],"verseLabel":"الحجر: 45","question":"لماذا جُمعت ونُكرت ﴿جَنَّاتٍ وَعُيُونٍ﴾؟","answer":"الجمع للتنوع والكثرة، والتنكير للتفخيم بما يفوق التصور.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص503.","url":""}]},{"id":"s15-87","number":87,"surah":15,"verses":[46],"verseLabel":"الحجر: 46","question":"ما سرّ التعبير بقوله تعالى: ﴿ادْخُلُوهَا بِسَلَامٍ آمِنِينَ﴾؟","answer":"جمع سلامة الدخول وأمن المستقبل؛ فلا ألم عند العبور ولا خوف بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص506-507.","url":""}]},{"id":"s15-88","number":88,"surah":15,"verses":[47],"verseLabel":"الحجر: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ﴾؟","answer":"النزع يدل على اقتلاع جذور الأثر الباطن، لتصفو الجنة من كل منغص نفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص511-513.","url":""}]},{"id":"s15-89","number":89,"surah":15,"verses":[47],"verseLabel":"الحجر: 47","question":"لماذا زاد هنا ﴿إِخْوَانًا﴾ على نظائر نزع الغل؟","answer":"لأن السياق لا يكتفي بزوال الضغينة، بل يصور تحول العلاقة إلى أخوة ظاهرة.","sources":[{"label":"الكرماني، أسرار التكرار، ص156؛ الموسوعة ج25، ص516.","url":""}]},{"id":"s15-90","number":90,"surah":15,"verses":[47],"verseLabel":"الحجر: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى سُرُرٍ مُتَقَابِلِينَ﴾؟","answer":"التقابل يمنع استدبار بعضهم بعضًا ويصور تمام الأنس والمساواة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص516.","url":""}]},{"id":"s15-91","number":91,"surah":15,"verses":[48],"verseLabel":"الحجر: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَمَسُّهُمْ فِيهَا نَصَبٌ﴾؟","answer":"المس أدنى الإصابة؛ فإذا نُفي أدناها انتفى كل تعب من باب أولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص521.","url":""}]},{"id":"s15-92","number":92,"surah":15,"verses":[48],"verseLabel":"الحجر: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا هُمْ مِنْهَا بِمُخْرَجِينَ﴾ لا «خالدون» فقط؟","answer":"ينفي عنهم قسر الإخراج واحتمال فقد النعيم، وهو أنسب بعد أمنهم واستقرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص522-523.","url":""}]},{"id":"s15-93","number":93,"surah":15,"verses":[49],"verseLabel":"الحجر: 49","question":"ما سرّ التعبير في قوله تعالى: ﴿نَبِّئْ عِبَادِي﴾ لا أخبرهم؟","answer":"التنبئة خبر عظيم الشأن، وصيغة التفعيل تشعر بتبليغه وتقريره.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص527-528.","url":""}]},{"id":"s15-94","number":94,"surah":15,"verses":[49],"verseLabel":"الحجر: 49","question":"لماذا أضاف العباد إليه؟","answer":"تشريف وتقريب يهيئ القلب لتلقي خبر المغفرة والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص528.","url":""}]},{"id":"s15-95","number":95,"surah":15,"verses":[49],"verseLabel":"الحجر: 49","question":"لماذا جمع بين ﴿الْغَفُورُ الرَّحِيمُ﴾؟","answer":"المغفرة تزيل الذنب، والرحمة تمنح الخير بعد الإزالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص529-530.","url":""}]},{"id":"s15-96","number":96,"surah":15,"verses":[50],"verseLabel":"الحجر: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنَّ عَذَابِي هُوَ الْعَذَابُ الْأَلِيمُ﴾؟","answer":"ضمير الفصل والتعريف يقصران كمال الإيلام على عذابه، ليوازن الرجاء بخوف جاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص532.","url":""}]},{"id":"s15-97","number":97,"surah":15,"verses":[51],"verseLabel":"الحجر: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَبِّئْهُمْ عَنْ ضَيْفِ إِبْرَاهِيمَ﴾؟","answer":"وصل الإنذار بقصة تجمع بشارة المؤمنين وهلاك المجرمين، فتشرح الصفتين السابقتين بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص536-537.","url":""}]},{"id":"s15-98","number":98,"surah":15,"verses":[51],"verseLabel":"الحجر: 51","question":"لماذا أُفرد ﴿ضَيْفِ﴾ مع أنهم جماعة؟","answer":"«ضيف» اسم جنس يصدق على الواحد والجمع، ويجمعهم في حكم الضيافة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص537-538.","url":""}]},{"id":"s15-99","number":99,"surah":15,"verses":[52],"verseLabel":"الحجر: 52","question":"ما سرّ التعبير في قول إبراهيم: ﴿إِنَّا مِنْكُمْ وَجِلُونَ﴾؟","answer":"الوجل خوف داخلي مفاجئ، وهو أدق من خوف مطلق بعد امتناعهم عن الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص544.","url":""}]},{"id":"s15-100","number":100,"surah":15,"verses":[53],"verseLabel":"الحجر: 53","question":"ما سرّ التعبير في قول الملائكة: ﴿لَا تَوْجَلْ﴾ مع حذف سبب الوجل؟","answer":"لإزالة كل خوف محتمل دفعة واحدة قبل إلقاء البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص551.","url":""}]},{"id":"s15-101","number":101,"surah":15,"verses":[54],"verseLabel":"الحجر: 54","question":"ما سرّ التعبير في قول إبراهيم: ﴿مَسَّنِيَ الْكِبَرُ﴾؟","answer":"المس كناية عن إصابة بلغت أثرها، لكنه ذكر العادة البشرية تعجبًا لا شكًا في القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص561.","url":""}]},{"id":"s15-102","number":102,"surah":15,"verses":[56],"verseLabel":"الحجر: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ يَقْنَطُ مِنْ رَحْمَةِ رَبِّهِ﴾؟","answer":"نسب الرحمة إلى الرب ليجمع الرجاء والرعاية، وجعل القنوط علامة ضلال عن معرفة القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص572-574.","url":""}]},{"id":"s15-103","number":103,"surah":15,"verses":[57],"verseLabel":"الحجر: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا خَطْبُكُمْ أَيُّهَا الْمُرْسَلُونَ﴾ وحذف «يا»؟","answer":"حذف حرف النداء لقربهم وحضورهم، و«الخطب» يسأل عن الأمر العظيم الذي جاءوا له.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص579.","url":""}]},{"id":"s15-104","number":104,"surah":15,"verses":[59],"verseLabel":"الحجر: 59","question":"ما سرّ تقديم ﴿آلَ لُوطٍ﴾ على وصف المرسلين؟","answer":"لأن إنجاء آل لوط هو موضع الاستثناء والعناية قبل بيان عموم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص587-594.","url":""}]},{"id":"s15-105","number":105,"surah":15,"verses":[60],"verseLabel":"الحجر: 60","question":"ما سرّ التعبير في قوله تعالى عن امرأة لوط: ﴿مِنَ الْغَابِرِينَ﴾ وحذف المتعلق؟","answer":"ليعم بقاؤها مع الهالكين وتخلفها عن كل نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص590.","url":""}]},{"id":"s15-106","number":106,"surah":15,"verses":[61,62,63],"verseLabel":"الحجر: 61-63","question":"ما سرّ التعبير في قول الملائكة للوط: ﴿بَلْ جِئْنَاكَ بِمَا كَانُوا فِيهِ يَمْتَرُونَ﴾؟","answer":"أضربوا عن إنكاره لهم إلى بيان الغاية: جاءوا بالعذاب الذي كان قومه يتكلفون الشك فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص598-604.","url":""}]},{"id":"s15-107","number":107,"surah":15,"verses":[63],"verseLabel":"الحجر: 63","question":"ما سرّ تقديم ﴿فِيهِ﴾ على ﴿يَمْتَرُونَ﴾؟","answer":"لتركيز الذم على أمر العذاب نفسه الذي أحاط به مراؤهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص603-604.","url":""}]},{"id":"s15-108","number":108,"surah":15,"verses":[65],"verseLabel":"الحجر: 65","question":"ما سرّ حذف متعلَّق ﴿تُؤْمَرُونَ﴾ في قوله تعالى: ﴿وَامْضُوا حَيْثُ تُؤْمَرُونَ﴾؟","answer":"التقدير: «حيث تؤمرون بالمضي إليه» أو «تؤمرون به»؛ وحذف المتعلَّق يفيد اتصافهم بالائتمار والامتثال لأي أمر يأتيهم من الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص616-617.","url":""}]},{"id":"s15-109","number":109,"surah":15,"verses":[66],"verseLabel":"الحجر: 66","question":"ما سرّ تقديم ﴿إِلَيْهِ﴾ في قوله تعالى: ﴿وَقَضَيْنَا إِلَيْهِ ذَلِكَ الْأَمْرَ﴾؟","answer":"تقديم الجار والمجرور يفيد تخصيص لوط عليه السلام بإخباره باستئصال قومه، اهتمامًا بشأنه ورعايةً لحق الرسالة، وليتهيأ هو وأتباعه للخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص622-624.","url":""}]},{"id":"s15-110","number":110,"surah":15,"verses":[66],"verseLabel":"الحجر: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿مَقْطُوعٌ﴾ لا هالك؟","answer":"تصوير لاستئصال آخر القوم حتى ينقطع امتدادهم تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص624.","url":""}]},{"id":"s15-111","number":111,"surah":15,"verses":[68],"verseLabel":"الحجر: 68","question":"ما سرّ التعبير في قول لوط: ﴿إِنَّ هَؤُلَاءِ ضَيْفِي﴾ باسم الإشارة؟","answer":"استحضرهم أمام القوم ليوقظ حرمة الضيافة ويجعل الجريمة مشهودة لا مجرد خبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص640.","url":""}]},{"id":"s15-112","number":112,"surah":15,"verses":[72],"verseLabel":"الحجر: 72","question":"لماذا أقسم الله بـ﴿لَعَمْرُكَ﴾؟","answer":"تشريف عظيم للنبي، أقسم بحياته على حال قوم أعماهم طغيانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص645-648.","url":""}]},{"id":"s15-113","number":113,"surah":15,"verses":[72],"verseLabel":"الحجر: 72","question":"لماذا فُتحت العين في ﴿لَعَمْرُكَ﴾ لا ضمت؟","answer":"جرى الاستعمال العربي على فتح «العَمر» في القسم، وخص الضم بمعنى مدة الحياة خارج القسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص648.","url":""}]},{"id":"s15-114","number":114,"surah":15,"verses":[72],"verseLabel":"الحجر: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي سَكْرَتِهِمْ يَعْمَهُونَ﴾؟","answer":"شبّه الشهوة المسكرة بحالة تغطي العقل، و«يعمهون» تصور ترددًا أعمى بلا اهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص649-650.","url":""}]},{"id":"s15-115","number":115,"surah":15,"verses":[72],"verseLabel":"الحجر: 72","question":"لماذا أُفردت ﴿سَكْرَتِهِمْ﴾؟","answer":"لأنهم اشتركوا في فتنة واحدة غالبة كأنها سكرة جماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص650.","url":""}]},{"id":"s15-116","number":116,"surah":15,"verses":[73],"verseLabel":"الحجر: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَخَذَتْهُمُ الصَّيْحَةُ مُشْرِقِينَ﴾؟","answer":"«مشرقين» حال تصورهم داخلين في ضوء الصباح حين باغتهم العذاب المرئي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص654-655.","url":""}]},{"id":"s15-117","number":117,"surah":15,"verses":[74],"verseLabel":"الحجر: 74","question":"ما سرّ التعبير في قوله تعالى: ﴿فَجَعَلْنَا عَالِيَهَا سَافِلَهَا﴾ لا قلبناها؟","answer":"«جعل» يصور تحويل الهيئة من حال إلى ضدها، فيرى السامع نتيجة الانقلاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص657.","url":""}]},{"id":"s15-118","number":118,"surah":15,"verses":[74],"verseLabel":"الحجر: 74","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿وَأَمْطَرْنَا عَلَيْهِمْ﴾، وفي مواضع: عليها؟","answer":"عاد الضمير هنا إلى القوم المجرمين المذكورين أول القصة، فركز العذاب على مستحقيه.","sources":[{"label":"الكرماني، أسرار التكرار، ص156؛ الموسوعة ج25، ص660.","url":""}]},{"id":"s15-119","number":119,"surah":15,"verses":[74],"verseLabel":"الحجر: 74","question":"ما سرّ تقديم ﴿عَلَيْهِمْ﴾ على ﴿حِجَارَةً﴾؟","answer":"لتعجيل بيان جهة الإصابة وأن المطر لم يكن ظاهرة عامة بل عقوبة مقصودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص660.","url":""}]},{"id":"s15-120","number":120,"surah":15,"verses":[74],"verseLabel":"الحجر: 74","question":"ما سرّ التعبير بقوله تعالى: ﴿حِجَارَةً مِنْ سِجِّيلٍ﴾؟","answer":"السجيل يصور حجارة عذاب معدة شديدة متتابعة، لا مطرًا مألوفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص662.","url":""}]},{"id":"s15-121","number":121,"surah":15,"verses":[75],"verseLabel":"الحجر: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿لَآيَاتٍ لِلْمُتَوَسِّمِينَ﴾ بالجمع؟","answer":"القصة تضم دلائل متعددة: الضيف والبشارة والإنذار والقلب والحجارة وآثار الديار.","sources":[{"label":"الكرماني، أسرار التكرار، ص156-157؛ الموسوعة ج25، ص665-666.","url":""}]},{"id":"s15-122","number":122,"surah":15,"verses":[75],"verseLabel":"الحجر: 75","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلْمُتَوَسِّمِينَ﴾؟","answer":"لمن يتفرس في العلامات ويتجاوز ظاهر الأثر إلى دلالته الأخلاقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص666.","url":""}]},{"id":"s15-123","number":123,"surah":15,"verses":[76],"verseLabel":"الحجر: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنَّهَا لَبِسَبِيلٍ مُقِيمٍ﴾؟","answer":"«مقيم» يصور الطريق ثابتًا مطروقًا، فالعبرة باقية أمام المسافرين لا خبرًا منقطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص670.","url":""}]},{"id":"s15-124","number":124,"surah":15,"verses":[78],"verseLabel":"الحجر: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿وَإِنْ كَانَ أَصْحَابُ الْأَيْكَةِ لَظَالِمِينَ﴾؟","answer":"وصفهم بالظلم لأنه جامع شركهم وبخسهم وإفسادهم، وهو سبب الانتقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص680.","url":""}]},{"id":"s15-125","number":125,"surah":15,"verses":[79],"verseLabel":"الحجر: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿فَانْتَقَمْنَا مِنْهُمْ﴾ لا عذبناهم؟","answer":"الانتقام جزاء عدل بعد الإصرار والاعتداء، فيربط العقوبة بسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص682.","url":""}]},{"id":"s15-126","number":126,"surah":15,"verses":[80],"verseLabel":"الحجر: 80","question":"لماذا سمّاهم ﴿أَصْحَابُ الْحِجْرِ﴾ لا ثمود؟","answer":"ليستحضر موطنهم المنحوت وآثاره المشاهدة، وهو الأنسب بسياق الطريق والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص689-690.","url":""}]},{"id":"s15-127","number":127,"surah":15,"verses":[80],"verseLabel":"الحجر: 80","question":"ما سرّ التعبير في قوله تعالى: ﴿كَذَّبَتْ... الْمُرْسَلِينَ﴾ مع أن رسولهم واحد؟","answer":"تكذيب رسول واحد تكذيب لأصل الرسالة الذي جاء به جميع الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص689-691.","url":""}]},{"id":"s15-128","number":128,"surah":15,"verses":[81],"verseLabel":"الحجر: 81","question":"لماذا جُمعت ﴿آيَاتِنَا﴾؟","answer":"لتعدد دلائل صدق صالح والمعجزات والإنذارات والآثار القائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص694.","url":""}]},{"id":"s15-129","number":129,"surah":15,"verses":[81],"verseLabel":"الحجر: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿فَكَانُوا عَنْهَا مُعْرِضِينَ﴾؟","answer":"الإعراض يصور معرفة الدليل ثم تولي الوجه عنه عمدًا، لا مجرد جهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص695.","url":""}]},{"id":"s15-130","number":130,"surah":15,"verses":[82],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿وَكَانُوا يَنْحِتُونَ﴾؟","answer":"«كانوا» مع المضارع تصور حرفة مستمرة وعادة راسخة صنعت لهم وهم الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص698.","url":""}]},{"id":"s15-131","number":131,"surah":15,"verses":[82],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿يَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتًا﴾، وفي الأعراف: ﴿تَنْحِتُونَ الْجِبَالَ بُيُوتًا﴾؟","answer":"«من الجبال» تبعيض يناسب استخراج البيوت من أجزائها، أما نصب الجبال في الأعراف فيبرز مباشرة النحت في جرمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص699-701؛ مسح عكسي.","url":""}]},{"id":"s15-132","number":132,"surah":15,"verses":[82],"verseLabel":"الحجر: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿آمِنِينَ﴾ وحذف ممَّ كانوا آمنين؟","answer":"ليصور أمنًا مطلقًا في زعمهم من العدو والانهيار والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص700.","url":""}]},{"id":"s15-133","number":133,"surah":15,"verses":[84],"verseLabel":"الحجر: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا أَغْنَى عَنْهُمْ مَا كَانُوا يَكْسِبُونَ﴾ لا نفع؟","answer":"الإغناء دفع للحاجة والضر، فنفى أن تغني عنهم قوتهم أدنى غناء ساعة العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص707.","url":""}]},{"id":"s15-134","number":134,"surah":15,"verses":[84],"verseLabel":"الحجر: 84","question":"لماذا عبّر بـ﴿يَكْسِبُونَ﴾ لا يبنون أو ينحتون؟","answer":"ليعم المباني والقوة والأموال وكل ما عدوه رصيدًا مكتسبًا للحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص709-710.","url":""}]},{"id":"s15-135","number":135,"surah":15,"verses":[85],"verseLabel":"الحجر: 85","question":"لماذا جُمعت السماوات وأُفردت الأرض؟","answer":"لتعدد العالم العلوي وظهور الأرض للإنسان قرارًا واحدًا، مع جمعهما في خلق بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص713.","url":""}]},{"id":"s15-136","number":136,"surah":15,"verses":[85],"verseLabel":"الحجر: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاصْفَحِ الصَّفْحَ الْجَمِيلَ﴾؟","answer":"الصفح الجميل إعراض بلا أذى ولا منّ ولا جزع، يناسب الثقة بقرب الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص719-721.","url":""}]},{"id":"s15-137","number":137,"surah":15,"verses":[86],"verseLabel":"الحجر: 86","question":"لماذا ختم بـ﴿إِنَّ رَبَّكَ هُوَ الْخَلَّاقُ الْعَلِيمُ﴾؟","answer":"«الخلاق» كثير الخلق قادر على الإعادة، و«العليم» يعلم ما يستحقه كل فريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص723-728.","url":""}]},{"id":"s15-138","number":138,"surah":15,"verses":[87],"verseLabel":"الحجر: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿آتَيْنَاكَ﴾ لا أعطيناك أو أوحينا؟","answer":"الإيتاء يشعر بتمكين النبي من نعمة باقية ينتفع بها، لا مجرد وقوع الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص730-731.","url":""}]},{"id":"s15-139","number":139,"surah":15,"verses":[87],"verseLabel":"الحجر: 87","question":"لماذا سميت الفاتحة ﴿سَبْعًا مِنَ الْمَثَانِي﴾؟","answer":"سبع آيات تتكرر في الصلاة وتثنّى في التلاوة، فجمع الاسم العدد والتكرار والتكريم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص730-734.","url":""}]},{"id":"s15-140","number":140,"surah":15,"verses":[87],"verseLabel":"الحجر: 87","question":"لماذا عطف ﴿وَالْقُرْآنَ الْعَظِيمَ﴾ على السبع المثاني؟","answer":"ذكر الخاص المشرف ثم عمّ القرآن كله، ليظهر عظم ما أوتيه أمام متاع الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص733-734.","url":""}]},{"id":"s15-141","number":141,"surah":15,"verses":[88],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾ لا تنظر؟","answer":"مد العين كناية عن إطالة نظر الرغبة والتطلع، لا مجرد رؤية عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص740.","url":""}]},{"id":"s15-142","number":142,"surah":15,"verses":[88],"verseLabel":"الحجر: 88","question":"لماذا ثنّى ﴿عَيْنَيْكَ﴾؟","answer":"للمبالغة في النهي عن استغراق النظر كله في زخرف ما عند الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص740.","url":""}]},{"id":"s15-143","number":143,"surah":15,"verses":[88],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِنْهُمْ﴾؟","answer":"«المتاع» مؤقت زائل، و«أزواجًا» أصناف متفاوتة اختبروا به، فلا يستحق الحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص741-743.","url":""}]},{"id":"s15-144","number":144,"surah":15,"verses":[88],"verseLabel":"الحجر: 88","question":"ما سرّ تقديم ﴿بِهِ﴾؟","answer":"لتركيز النهي على نفس المتاع الذي فُتنوا به، مع تحقير قيمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص743.","url":""}]},{"id":"s15-145","number":145,"surah":15,"verses":[88],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَحْزَنْ عَلَيْهِمْ﴾؟","answer":"نهى عن ألم الحسرة على إعراضهم بعد أن بلّغ، لا عن الرحمة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص745-746.","url":""}]},{"id":"s15-146","number":146,"surah":15,"verses":[88],"verseLabel":"الحجر: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ﴾؟","answer":"استعارة من الطائر تضم معنى اللين والحماية والقرب، بعد النهي عن التطلع للكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص748-749.","url":""}]},{"id":"s15-147","number":147,"surah":15,"verses":[89],"verseLabel":"الحجر: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنِّي أَنَا النَّذِيرُ الْمُبِينُ﴾ ولم يذكر البشير؟","answer":"المقام مواجهة للمقتسمين المكذبين، فناسب تثبيت وصف الإنذار الواضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص752-754.","url":""}]},{"id":"s15-148","number":148,"surah":15,"verses":[90],"verseLabel":"الحجر: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿كَمَا أَنْزَلْنَا عَلَى الْمُقْتَسِمِينَ﴾؟","answer":"شبّه إنذاره بعذاب سابق نزل بمن قسموا الحق أو القرآن، ليتحول الوعيد إلى سابقة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص757-758.","url":""}]},{"id":"s15-149","number":149,"surah":15,"verses":[91],"verseLabel":"الحجر: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿جَعَلُوا الْقُرْآنَ عِضِينَ﴾؟","answer":"«عضين» أجزاء ممزقة؛ صوروا موقفًا ينتقي بعض القرآن ويهجر بعضه أو يوزع عليه التهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص763-765.","url":""}]},{"id":"s15-150","number":150,"surah":15,"verses":[92],"verseLabel":"الحجر: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿لَنَسْأَلَنَّهُمْ أَجْمَعِينَ﴾ ثم ﴿عَمَّا كَانُوا يَعْمَلُونَ﴾؟","answer":"أكد شمول الأشخاص ثم شمول الأعمال، فلا يفلت أحد ولا فعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص769.","url":""}]},{"id":"s15-151","number":151,"surah":15,"verses":[94],"verseLabel":"الحجر: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ﴾ لا فبلّغ؟","answer":"الصدع شق وإظهار قوي؛ يأمر بإعلان الحق الذي يفصل بينه وبين الباطل بلا مواربة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص775-777.","url":""}]},{"id":"s15-152","number":152,"surah":15,"verses":[94],"verseLabel":"الحجر: 94","question":"لماذا بُني ﴿تُؤْمَرُ﴾ للمفعول؟","answer":"لأن الآمر معلوم معظم، والتركيز على وجوب تنفيذ المأمور به كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص777.","url":""}]},{"id":"s15-153","number":153,"surah":15,"verses":[95],"verseLabel":"الحجر: 95","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّا كَفَيْنَاكَ الْمُسْتَهْزِئِينَ﴾؟","answer":"أطلق الكفاية لتعم الحماية من أذاهم ومكرهم، ووعده بكفاية هؤلاء دليل على من دونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص783-785.","url":""}]},{"id":"s15-154","number":154,"surah":15,"verses":[96],"verseLabel":"الحجر: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿يَجْعَلُونَ مَعَ اللَّهِ إِلَهًا آخَرَ﴾ لا ربًا؟","answer":"لأن جريمتهم صرف العبادة والتأله لغيره، و«إلهًا» هو اللفظ المطابق لمحل الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص785-787.","url":""}]},{"id":"s15-155","number":155,"surah":15,"verses":[96],"verseLabel":"الحجر: 96","question":"لماذا نُكر ﴿إِلَهًا آخَرَ﴾؟","answer":"يصوّر أنهم يقبلون أي معبود يوافق الهوى، لا برهان لهم على معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص787.","url":""}]},{"id":"s15-156","number":156,"surah":15,"verses":[96],"verseLabel":"الحجر: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿فَسَوْفَ يَعْلَمُونَ﴾ لا فسيعلمون؟","answer":"«سوف» توسع زمن الوعيد الظاهر مع تحقيقه، وفي الإمهال زيادة تهديد لا نفي للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص787-788.","url":""}]},{"id":"s15-157","number":157,"surah":15,"verses":[97],"verseLabel":"الحجر: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿نَعْلَمُ أَنَّكَ يَضِيقُ صَدْرُكَ﴾؟","answer":"الإخبار بالعلم تسلية قبل التكليف؛ ضيقه معلوم عند ربه وليس متروكًا وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص788-793.","url":""}]},{"id":"s15-158","number":158,"surah":15,"verses":[97],"verseLabel":"الحجر: 97","question":"لماذا أُسند الضيق إلى الصدر لا القلب؟","answer":"الصدر وعاء المشاعر الذي يحس بالانقباض والاتساع، فناسب أثر أقوالهم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص793-795.","url":""}]},{"id":"s15-159","number":159,"surah":15,"verses":[98],"verseLabel":"الحجر: 98","question":"لماذا كان العلاج: ﴿فَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"لأن التسبيح المصحوب بحمد الله والصلاة والعبادة مما يزيل ضيق الصدر والفزع؛ فجمع له بين تنزيه ربه والثناء عليه والتوجه إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص801.","url":""}]},{"id":"s15-160","number":160,"surah":15,"verses":[98],"verseLabel":"الحجر: 98","question":"لماذا أضيف الحمد إلى ﴿رَبِّكَ﴾؟","answer":"إضافة الحمد تفيد اختصاص الرب سبحانه بالحمد، واختيار ﴿ربك﴾ مع إضافته إلى ضمير النبي ﷺ يتضمن لطفًا به؛ فهو مدبر أمره ومربيه والمحسن إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص801.","url":""}]},{"id":"s15-161","number":161,"surah":15,"verses":[99],"verseLabel":"الحجر: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاعْبُدْ رَبَّكَ حَتَّى يَأْتِيَكَ الْيَقِينُ﴾؟","answer":"جعل العبادة ممتدة إلى الموت؛ فلا مقام يسقط فيه التكليف ما دام الإنسان حيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص804-805.","url":""}]},{"id":"s15-162","number":162,"surah":15,"verses":[99],"verseLabel":"الحجر: 99","question":"لماذا سمّى الموت ﴿الْيَقِينَ﴾؟","answer":"لأنه الأمر المقطوع بمجيئه، وعنده تنكشف حقائق الآخرة يقينًا بالمشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص804.","url":""}]},{"id":"s15-163","number":163,"surah":15,"verses":[99],"verseLabel":"الحجر: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿يَأْتِيَكَ﴾ لا يجيئك؟","answer":"اختير الإتيان دون المجيء للإشعار بأن إتيان الموت سهل يسير، وأنه ليس بينه وبين العبد إلا انقضاء الوقت وحلول الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج25، ص805.","url":""}]},{"id":"s16-1","number":1,"surah":16,"verses":[1],"verseLabel":"النحل: 1","question":"لماذا افتتحت السورة بالماضي: ﴿أَتَى أَمْرُ اللَّهِ﴾ مع أن القيامة لم تقع؟","answer":"لتحقيق الوقوع؛ ما وعد الله به محقق حتى صح التعبير عنه كأنه أتى وانتهى.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص23-29.","url":""}]},{"id":"s16-2","number":2,"surah":16,"verses":[1],"verseLabel":"النحل: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿أَمْرُ اللَّهِ﴾ لا عذاب الله؟","answer":"عُبّر بـ﴿أمر الله﴾ تهويلًا وتعظيمًا للموعود؛ فهو ما قدّره الله وأراد وقوعه في أجله، وإضافته إلى اسم الجلالة تزيده عظمةً وهيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص23-29.","url":""}]},{"id":"s16-3","number":3,"surah":16,"verses":[1],"verseLabel":"النحل: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿فَلَا تَسْتَعْجِلُوهُ﴾ بعد ﴿أتى﴾؟","answer":"جمع تحقق الموعود مع نهيهم عن طلب تعجيل ظهوره؛ فهو آتٍ حتمًا لكن في وقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص27-31.","url":""}]},{"id":"s16-4","number":4,"surah":16,"verses":[1],"verseLabel":"النحل: 1","question":"لماذا خُتمت الآية بـ﴿سُبْحَانَهُ وَتَعَالَى عَمَّا يُشْرِكُونَ﴾؟","answer":"لأن القادر على إنفاذ أمره منزه عن شركاء يعجزون عن خلق أو تدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص31-38.","url":""}]},{"id":"s16-5","number":5,"surah":16,"verses":[2],"verseLabel":"النحل: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿يُنَزِّلُ الْمَلَائِكَةَ بِالرُّوحِ﴾؟","answer":"سمي الوحي روحًا لأنه يحيي القلوب كما تحيي الروح الأجساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص38-44.","url":""}]},{"id":"s16-6","number":6,"surah":16,"verses":[2],"verseLabel":"النحل: 2","question":"لماذا جُمعت ﴿الْمَلَائِكَةَ﴾ وعُرّفت؟","answer":"لاستغراق جنس الملائكة الذين يقومون بأمر الوحي، وفي مقدمتهم جبريل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص41.","url":""}]},{"id":"s16-7","number":7,"surah":16,"verses":[2],"verseLabel":"النحل: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ أَمْرِهِ﴾؟","answer":"ليؤكد أن الوحي صادر بأمره وحده، لا باجتهاد ملك أو رسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص41-45.","url":""}]},{"id":"s16-8","number":8,"surah":16,"verses":[2],"verseLabel":"النحل: 2","question":"لماذا لخّص الوحي في ﴿أَنْ أَنْذِرُوا أَنَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"لأن التوحيد أصل الرسالات، والإنذار يوقظ من الشرك قبل تفصيل العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص44-48.","url":""}]},{"id":"s16-9","number":9,"surah":16,"verses":[3],"verseLabel":"النحل: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ بِالْحَقِّ﴾؟","answer":"ينفي العبث، ويجعل الخلق نفسه حجة على التوحيد والبعث والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص49-56.","url":""}]},{"id":"s16-10","number":10,"surah":16,"verses":[4],"verseLabel":"النحل: 4","question":"ما سرّ التعبير في قوله تعالى عن الإنسان: ﴿فَإِذَا هُوَ خَصِيمٌ مُبِينٌ﴾؟","answer":"الفاء تفاجئ بانقلاب النطفة الضعيفة إلى مجادل ظاهر الخصومة لربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص56-62.","url":""}]},{"id":"s16-11","number":11,"surah":16,"verses":[4],"verseLabel":"النحل: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿خَصِيمٌ﴾ لا مجادل؟","answer":"الخصيم وصف ثابت يوحي بتمكن الخصومة، لا مجرد صدور جدال عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص58-62.","url":""}]},{"id":"s16-12","number":12,"surah":16,"verses":[5],"verseLabel":"النحل: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالْأَنْعَامَ خَلَقَهَا لَكُمْ﴾ وقدّمها؟","answer":"فصل خلقها للعناية بعظم منفعتها للإنسان، ثم فصّل الدفء والمنافع والأكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص81-88.","url":""}]},{"id":"s16-13","number":13,"surah":16,"verses":[5],"verseLabel":"النحل: 5","question":"لماذا عُرّفت ﴿الْأَنْعَامَ﴾؟","answer":"لاستحضار الجنس المعروف كله، لا أفرادًا مخصوصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص83.","url":""}]},{"id":"s16-14","number":14,"surah":16,"verses":[5],"verseLabel":"النحل: 5","question":"لماذا قدّم ﴿دِفْءٌ﴾ على المنافع والأكل؟","answer":"لأنه من حاجات البقاء المباشرة وميزة ظاهرة في الأنعام، ثم عطف عموم المنافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص84-90.","url":""}]},{"id":"s16-15","number":15,"surah":16,"verses":[6],"verseLabel":"النحل: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿لَكُمْ فِيهَا جَمَالٌ﴾؟","answer":"لفت إلى نعمة نفسية لا مادية فقط؛ منظرها عند الرواح والسراح يبهج ويمنح المكان حياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص91-99.","url":""}]},{"id":"s16-16","number":16,"surah":16,"verses":[6],"verseLabel":"النحل: 6","question":"ما سرّ تقديم الرواح على السراح؟","answer":"الرواح وقت امتلائها وعودتها مجتمعة إلى أهلها، فهو أجمل وأوقع في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص94-99.","url":""}]},{"id":"s16-17","number":17,"surah":16,"verses":[7],"verseLabel":"النحل: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿تَحْمِلُ أَثْقَالَكُمْ﴾ بالمضارع؟","answer":"لتصوير المنفعة متجددة في كل سفر وحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص100-107.","url":""}]},{"id":"s16-18","number":18,"surah":16,"verses":[7],"verseLabel":"النحل: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَى بَلَدٍ لَمْ تَكُونُوا بَالِغِيهِ إِلَّا بِشِقِّ الْأَنْفُسِ﴾؟","answer":"استحضر المشقة التي رفعتها الأنعام ليُرى قدر النعمة بالمقارنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص104-110.","url":""}]},{"id":"s16-19","number":19,"surah":16,"verses":[7],"verseLabel":"النحل: 7","question":"لماذا ختم بـ﴿رَءُوفٌ رَحِيمٌ﴾؟","answer":"الرأفة تناسب رفع المشقة، والرحمة تعم سائر وجوه الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص109-113.","url":""}]},{"id":"s16-20","number":20,"surah":16,"verses":[8],"verseLabel":"النحل: 8","question":"لماذا ذُكرت الخيل والبغال والحمير منفصلة عن الأنعام؟","answer":"لأن السياق انتقل من الدفء والأكل إلى الركوب والزينة، وهي منافعها الأظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص114-121.","url":""}]},{"id":"s16-21","number":21,"surah":16,"verses":[8],"verseLabel":"النحل: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتَرْكَبُوهَا وَزِينَةً﴾؟","answer":"جمع المنفعة الضرورية والبهجة الزائدة، ليبين تمام الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص116-121.","url":""}]},{"id":"s16-22","number":22,"surah":16,"verses":[8],"verseLabel":"النحل: 8","question":"لماذا ختم بـ﴿وَيَخْلُقُ مَا لَا تَعْلَمُونَ﴾؟","answer":"فتح أفق النعم لما يستحدث ويخفى، فلا يحصر الخلق في وسائل النقل المعروفة زمن التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص121.","url":""}]},{"id":"s16-23","number":23,"surah":16,"verses":[9],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَلَى اللَّهِ قَصْدُ السَّبِيلِ﴾؟","answer":"تقديم الجار يفيد أن بيان الطريق المستقيم وهدايته تفضل تكفل الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص126-134.","url":""}]},{"id":"s16-24","number":24,"surah":16,"verses":[9],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿قَصْدُ السَّبِيلِ﴾ لا السبيل القاصد؟","answer":"المصدر يبرز استقامة الطريق ووضوح وجهته كحقيقة ثابتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص128-134.","url":""}]},{"id":"s16-25","number":25,"surah":16,"verses":[9],"verseLabel":"النحل: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمِنْهَا جَائِرٌ﴾؟","answer":"قابل الطريق القاصد بطرق مائلة كثيرة، فدل على وحدة الحق وتعدد الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص132-136.","url":""}]},{"id":"s16-26","number":26,"surah":16,"verses":[10],"verseLabel":"النحل: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿هُوَ الَّذِي أَنْزَلَ مِنَ السَّمَاءِ مَاءً﴾؟","answer":"تعريف طرفي الإسناد في ﴿هُوَ الَّذِي أَنْزَلَ﴾ يفيد قصر الإنزال على الله وحده، وفي الموصول وصلته تعظيم للمنعم بذكر نعمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص134.","url":""}]},{"id":"s16-27","number":27,"surah":16,"verses":[10],"verseLabel":"النحل: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْهُ شَرَابٌ وَمِنْهُ شَجَرٌ﴾؟","answer":"قسم الماء بحسب نفعه المباشر للإنسان ونفعه في النبات الذي ترعى فيه الأنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص137-139.","url":""}]},{"id":"s16-28","number":28,"surah":16,"verses":[11],"verseLabel":"النحل: 11","question":"لماذا فُصّلت المزروعات: الزرع والزيتون والنخيل والأعناب؟","answer":"لجمع القوت والزيت والثمر، ثم عمم بقوله ﴿ومن كل الثمرات﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص140-148.","url":""}]},{"id":"s16-29","number":29,"surah":16,"verses":[11],"verseLabel":"النحل: 11","question":"لماذا خُتمت بـ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن إدراك ما في إنبات هذه الأصناف من دلالة على وجود الله وكمال قدرته ووحدانيته يحتاج إلى التفكر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص148-151.","url":""}]},{"id":"s16-30","number":30,"surah":16,"verses":[11],"verseLabel":"النحل: 11","question":"لماذا أُفردت ﴿آيَةً﴾ هنا؟","answer":"لأن المدلول الجامع واحد: إخراج النبات المتنوع بالماء الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص149.","url":""}]},{"id":"s16-31","number":31,"surah":16,"verses":[12],"verseLabel":"النحل: 12","question":"لماذا جُمعت ﴿لَآيَاتٍ﴾ بعد تسخير الليل والنهار والشمس والقمر والنجوم؟","answer":"لتعدد المسخرات وتنوع دلالاتها، فوافق الجمع كثرة المشاهد.","sources":[{"label":"الكرماني، أسرار التكرار، ص158؛ الموسوعة ج26، ص161-173.","url":""}]},{"id":"s16-32","number":32,"surah":16,"verses":[12],"verseLabel":"النحل: 12","question":"ما سرّ تقديم الليل على النهار؟","answer":"لأن الليل يسبق النهار في الحساب الشرعي وفي دورة السكون ثم الحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص166-171.","url":""}]},{"id":"s16-33","number":33,"surah":16,"verses":[12],"verseLabel":"النحل: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿مُسَخَّرَاتٌ بِأَمْرِهِ﴾؟","answer":"التسخير يدل على دوام الانقياد في نظام لا تختاره هذه الأجرام لنفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص169-173.","url":""}]},{"id":"s16-34","number":34,"surah":16,"verses":[13],"verseLabel":"النحل: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مُخْتَلِفًا أَلْوَانُهُ﴾؟","answer":"اختلاف اللون كناية عن تنوع الأنواع والصفات والمنافع في أرض واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص176-184.","url":""}]},{"id":"s16-35","number":35,"surah":16,"verses":[14],"verseLabel":"النحل: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وَهُوَ الَّذِي سَخَّرَ الْبَحْرَ﴾؟","answer":"عاد إلى ضمير الفصل لتخصيصه بتذليل مخلوق هائل لمنافع البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص184-194.","url":""}]},{"id":"s16-36","number":36,"surah":16,"verses":[14],"verseLabel":"النحل: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿لَحْمًا طَرِيًّا﴾؟","answer":"وصفه بالطراوة مع خروجه من ماء ملح لإبراز القدرة والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص188-194.","url":""}]},{"id":"s16-37","number":37,"surah":16,"verses":[15],"verseLabel":"النحل: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ تَمِيدَ بِكُمْ﴾؟","answer":"بيّن غاية إلقاء الرواسي: كراهة أن تضطرب الأرض بأهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص195-201.","url":""}]},{"id":"s16-38","number":38,"surah":16,"verses":[15],"verseLabel":"النحل: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَنْهَارًا وَسُبُلًا لَعَلَّكُمْ تَهْتَدُونَ﴾؟","answer":"جمع طرق الماء وطرق السير؛ بها هداية الأبدان إلى معاشها، ومنها إشارة لهداية القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص199-204.","url":""}]},{"id":"s16-39","number":39,"surah":16,"verses":[16],"verseLabel":"النحل: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعَلَامَاتٍ وَبِالنَّجْمِ هُمْ يَهْتَدُونَ﴾؟","answer":"عمم العلامات الأرضية ثم خص النجم بالذكر لعظم دوره في ظلمات البر والبحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص204-211.","url":""}]},{"id":"s16-40","number":40,"surah":16,"verses":[17],"verseLabel":"النحل: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ يَخْلُقُ كَمَنْ لَا يَخْلُقُ﴾؟","answer":"استفهام يحول براهين النعم إلى نتيجة بدهيّة: لا يستوي الخالق والعاجز المخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص212-220.","url":""}]},{"id":"s16-41","number":41,"surah":16,"verses":[18],"verseLabel":"النحل: 18","question":"لماذا أُفردت ﴿نِعْمَةَ اللَّهِ﴾ مع استحالة العد؟","answer":"اسم جنس؛ بل النعمة الواحدة تتشعب إلى نعم لا يحصيها الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص220-228.","url":""}]},{"id":"s16-42","number":42,"surah":16,"verses":[18],"verseLabel":"النحل: 18","question":"لماذا ختم بـ﴿غَفُورٌ رَحِيمٌ﴾؟","answer":"لأن العجز عن الشكر والتقصير في إحصاء النعم محتاج إلى مغفرة ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص225-229.","url":""}]},{"id":"s16-43","number":43,"surah":16,"verses":[19],"verseLabel":"النحل: 19","question":"لماذا جمع بين ﴿مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾؟","answer":"ليستوي في علمه أدق الباطن وأوضح الظاهر، فتقوم حجة الإخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص229-236.","url":""}]},{"id":"s16-44","number":44,"surah":16,"verses":[20],"verseLabel":"النحل: 20","question":"ما سرّ التعبير في قوله تعالى عن المعبودات: ﴿أَمْوَاتٌ غَيْرُ أَحْيَاءٍ﴾؟","answer":"لم يكتف بالموت، بل نفى عنها أصل الحياة توكيدًا لعجزها عن الخلق والإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص236-244.","url":""}]},{"id":"s16-45","number":45,"surah":16,"verses":[21],"verseLabel":"النحل: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ﴾؟","answer":"من لا يشعر ببعث نفسه فضلاً عن عابديه لا يصلح إلهًا يُرجى أو يُخاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص244-251.","url":""}]},{"id":"s16-46","number":46,"surah":16,"verses":[22],"verseLabel":"النحل: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"كرر الاسم لإثبات حقيقة الألوهية ثم قصرها على الواحد، لا وحدة عددية فحسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص251-258.","url":""}]},{"id":"s16-47","number":47,"surah":16,"verses":[22],"verseLabel":"النحل: 22","question":"لماذا وصف القلوب بالإنكار؟","answer":"جعل الإنكار مستقرًا في القلوب، فالمشكلة ليست نقص البيان بل رفض باطني.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص255-262.","url":""}]},{"id":"s16-48","number":48,"surah":16,"verses":[22],"verseLabel":"النحل: 22","question":"لماذا ختم بـ﴿وَهُمْ مُسْتَكْبِرُونَ﴾؟","answer":"الاستكبار هو العلة التي منعت القلب من الإقرار مع وضوح الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص259-264.","url":""}]},{"id":"s16-49","number":49,"surah":16,"verses":[23],"verseLabel":"النحل: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا جَرَمَ﴾؟","answer":"تركيب تحقيق وقطع، يقرر علم الله بالسر والعلن وجزاء المستكبرين بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص264-270.","url":""}]},{"id":"s16-50","number":50,"surah":16,"verses":[24],"verseLabel":"النحل: 24","question":"ما وجه قولهم: ﴿أَسَاطِيرُ الْأَوَّلِينَ﴾؟","answer":"نسبوا الوحي إلى حكايات قديمة لتجريده من سلطان الحاضر ومصدره الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص270-278.","url":""}]},{"id":"s16-51","number":51,"surah":16,"verses":[25],"verseLabel":"النحل: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿لِيَحْمِلُوا أَوْزَارَهُمْ كَامِلَةً﴾؟","answer":"الأوزار تصور الذنوب أحمالًا ثقيلة، و«كاملة» تنفي سقوط شيء منها بغير توبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص278-286.","url":""}]},{"id":"s16-52","number":52,"surah":16,"verses":[25],"verseLabel":"النحل: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمِنْ أَوْزَارِ الَّذِينَ يُضِلُّونَهُمْ﴾؟","answer":"يحمل المضل نصيب التسبب، من غير أن ينقص من وزر المقلد المسؤول.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص281-287.","url":""}]},{"id":"s16-53","number":53,"surah":16,"verses":[27],"verseLabel":"النحل: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَتَى اللَّهُ بُنْيَانَهُمْ مِنَ الْقَوَاعِدِ﴾؟","answer":"استعارة تقلب موضع الأمن نفسه إلى مبدأ الهدم؛ جاءت الضربة من الأساس الذي وثقوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص287-300.","url":""}]},{"id":"s16-54","number":54,"surah":16,"verses":[27],"verseLabel":"النحل: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿فَخَرَّ عَلَيْهِمُ السَّقْفُ مِنْ فَوْقِهِمْ﴾ مع أن السقف فوق؟","answer":"زيادة ﴿من فوقهم﴾ تستحضر المباغتة والإحاطة وتمنع توهم خرور بعيد عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص295-301.","url":""}]},{"id":"s16-55","number":55,"surah":16,"verses":[28],"verseLabel":"النحل: 28","question":"ما وجه قولهم يوم القيامة: ﴿مَا كُنَّا نَعْمَلُ مِنْ سُوءٍ﴾؟","answer":"استمروا في الإنكار، فجاء ﴿بلى﴾ شاهدًا بأن علم الله أحاط بما كانوا يجددونه من سوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص301-312.","url":""}]},{"id":"s16-56","number":56,"surah":16,"verses":[29],"verseLabel":"النحل: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿فَادْخُلُوا أَبْوَابَ جَهَنَّمَ﴾ بالجمع؟","answer":"لتعدد طبقاتها ومداخلها بحسب أصناف الكبر والجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص312-320.","url":""}]},{"id":"s16-57","number":57,"surah":16,"verses":[30],"verseLabel":"النحل: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَدَارُ الْآخِرَةِ خَيْرٌ﴾ لا الجنة فقط؟","answer":"«دار الآخرة» تجمع تمام المقام والبقاء والجزاء، وتواجه اختيار الدنيا الزائلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص322.","url":""}]},{"id":"s16-58","number":58,"surah":16,"verses":[31],"verseLabel":"النحل: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ﴾؟","answer":"تصور الماء ملازمًا لأصول الجنات، لا طارئًا يحتاج إلى جلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص322-334.","url":""}]},{"id":"s16-59","number":59,"surah":16,"verses":[32],"verseLabel":"النحل: 32","question":"ما سرّ التعبير في قول الملائكة: ﴿سَلَامٌ عَلَيْكُمُ ادْخُلُوا الْجَنَّةَ﴾؟","answer":"قدمت الأمان والتحية قبل الأمر بالدخول، فزال الخوف ثم تم النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص334-342.","url":""}]},{"id":"s16-60","number":60,"surah":16,"verses":[33],"verseLabel":"النحل: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿هَلْ يَنْظُرُونَ إِلَّا أَنْ تَأْتِيَهُمُ الْمَلَائِكَةُ﴾؟","answer":"استفهام تهكمي: بعد استنفاد الحجج لم يبق في انتظارهم إلا الموت أو العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص342-352.","url":""}]},{"id":"s16-61","number":61,"surah":16,"verses":[34],"verseLabel":"النحل: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿فَأَصَابَهُمْ سَيِّئَاتُ مَا عَمِلُوا﴾، وفي مواضع: ما كسبوا؟","answer":"«عملوا» أعم، وناسب تكرار مادة العمل قبلها وبعدها في السورة.","sources":[{"label":"الكرماني، أسرار التكرار، ص159-160؛ الموسوعة ج26، ص361.","url":""}]},{"id":"s16-62","number":62,"surah":16,"verses":[35],"verseLabel":"النحل: 35","question":"ما وجه قول المشركين: ﴿لَوْ شَاءَ اللَّهُ مَا عَبَدْنَا﴾؟","answer":"احتجوا بالمشيئة الكونية على مخالفة الأمر الشرعي، فهربوا من مسؤولية الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص365-377.","url":""}]},{"id":"s16-63","number":63,"surah":16,"verses":[36],"verseLabel":"النحل: 36","question":"ما سرّ التعبير في قوله تعالى: ﴿فِي كُلِّ أُمَّةٍ رَسُولًا﴾؟","answer":"ليثبت عموم الحجة عبر التاريخ؛ لا أمة تُركت بلا بيان أصل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص377-390.","url":""}]},{"id":"s16-64","number":64,"surah":16,"verses":[36],"verseLabel":"النحل: 36","question":"لماذا جمعت الرسالة بين ﴿اعْبُدُوا اللَّهَ﴾ و﴿اجْتَنِبُوا الطَّاغُوتَ﴾؟","answer":"التوحيد إثبات عبادة الله ونفي كل معبود وطاعة متجاوزة لحده؛ لا يكتمل أحدهما دون الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص390-405.","url":""}]},{"id":"s16-65","number":65,"surah":16,"verses":[36],"verseLabel":"النحل: 36","question":"لماذا اختير لفظ ﴿الطَّاغُوتَ﴾؟","answer":"لفظ جامع لكل ما تجاوز به العبد الحد من معبود أو متبوع أو مطاع في الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص403.","url":""}]},{"id":"s16-66","number":66,"surah":16,"verses":[37],"verseLabel":"النحل: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنْ تَحْرِصْ عَلَى هُدَاهُمْ﴾؟","answer":"يقر بعظم حرص النبي ثم يفصل قدرته عن نتيجة الهداية التي اختاروا صدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص405-417.","url":""}]},{"id":"s16-67","number":67,"surah":16,"verses":[38],"verseLabel":"النحل: 38","question":"لماذا أقسموا ﴿جَهْدَ أَيْمَانِهِمْ﴾ أن الله لا يبعث؟","answer":"لإظهار المفارقة: بذلوا أقصى التوكيد في إنكار أمر هو وعد حق على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص417-430.","url":""}]},{"id":"s16-68","number":68,"surah":16,"verses":[38],"verseLabel":"النحل: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿وَعْدًا عَلَيْهِ حَقًّا﴾؟","answer":"جعل البعث وعدًا تفضل بإيجابه على نفسه، ثم أكده بالحق ليقطع الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص425-431.","url":""}]},{"id":"s16-69","number":69,"surah":16,"verses":[40],"verseLabel":"النحل: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"أوجز كمال القدرة في أمر واحد لا يحتاج معالجة ولا زمنًا بين الإرادة والوجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص431-440.","url":""}]},{"id":"s16-70","number":70,"surah":16,"verses":[41,42],"verseLabel":"النحل: 41-42","question":"لماذا جمع بين الهجرة والصبر والتوكل؟","answer":"الهجرة مفارقة، والصبر احتمال كلفتها، والتوكل سند القلب في مجهول الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص440-448.","url":""}]},{"id":"s16-71","number":71,"surah":16,"verses":[43],"verseLabel":"النحل: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاسْأَلُوا أَهْلَ الذِّكْرِ﴾؟","answer":"يرد شبهة بشرية الرسل إلى أهل العلم بالوحي السابق، فيحتج عليهم بما يقرون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص448-461.","url":""}]},{"id":"s16-72","number":72,"surah":16,"verses":[44],"verseLabel":"النحل: 44","question":"ما سرّ التعبير في قوله تعالى: ﴿لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ﴾؟","answer":"يثبت وظيفة البيان النبوي مع بقاء مصدر التشريع في المنزل من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص461-478.","url":""}]},{"id":"s16-73","number":73,"surah":16,"verses":[44],"verseLabel":"النحل: 44","question":"لماذا ختم بـ﴿لَعَلَّهُمْ يَتَفَكَّرُونَ﴾؟","answer":"البيان يرفع الغموض، ثم يبقى على الناس أن يعملوا الفكر حتى يبلغوا المراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص475-482.","url":""}]},{"id":"s16-74","number":74,"surah":16,"verses":[45],"verseLabel":"النحل: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ يَخْسِفَ اللَّهُ بِهِمُ الْأَرْضَ﴾؟","answer":"الخسف يجعل موضع استقرارهم نفسه يبتلعهم، فيبطل شعور الأمن من أساسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص482-493.","url":""}]},{"id":"s16-75","number":75,"surah":16,"verses":[46],"verseLabel":"النحل: 46","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَأْخُذَهُمْ فِي تَقَلُّبِهِمْ﴾؟","answer":"أي أثناء حركتهم في المعاش والسفر؛ العذاب لا يحتاج انتظار سكونهم أو استعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص493-501.","url":""}]},{"id":"s16-76","number":76,"surah":16,"verses":[47],"verseLabel":"النحل: 47","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْ يَأْخُذَهُمْ عَلَى تَخَوُّفٍ﴾؟","answer":"أي على تنقص تدريجي أو حال خوف؛ فالعقوبة قد تفجأ وقد تتدرج أمام العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص501-512.","url":""}]},{"id":"s16-77","number":77,"surah":16,"verses":[47],"verseLabel":"النحل: 47","question":"لماذا ختم بـ﴿رَءُوفٌ رَحِيمٌ﴾ بعد صور الأخذ؟","answer":"لأن الإمهال والتحذير قبل المؤاخذة رأفة ورحمة، لا عجزًا عن الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص510-518.","url":""}]},{"id":"s16-78","number":78,"surah":16,"verses":[48],"verseLabel":"النحل: 48","question":"ما سرّ التعبير بقوله تعالى: عن الظلال: ﴿يَتَفَيَّأُ ظِلَالُهُ عَنِ الْيَمِينِ وَالشَّمَائِلِ سُجَّدًا﴾؟","answer":"حركة الظل من جهة إلى جهات ترسم خضوع المخلوق كله لنظام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص518-530.","url":""}]},{"id":"s16-79","number":79,"surah":16,"verses":[48],"verseLabel":"النحل: 48","question":"لماذا جُمعت الشمائل وأُفرد اليمين؟","answer":"اليمين جهة البدء عند طلوع الشمس، ثم تتعدد جهات رجوع الظلال وامتدادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص524-530.","url":""}]},{"id":"s16-80","number":80,"surah":16,"verses":[49],"verseLabel":"النحل: 49","question":"لماذا خص الدواب والملائكة بعد العموم؟","answer":"أبرز ما يتحرك على الأرض وما هو أشرف في السماء، ثم نفى عن الملائكة الاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص530-541.","url":""}]},{"id":"s16-81","number":81,"surah":16,"verses":[50],"verseLabel":"النحل: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ﴾؟","answer":"«من فوقهم» تفيد علو القهر والسلطان، لا تحديدًا مكانيًا يحيط به.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص541-550.","url":""}]},{"id":"s16-82","number":82,"surah":16,"verses":[50],"verseLabel":"النحل: 50","question":"لماذا ختم بـ﴿وَيَفْعَلُونَ مَا يُؤْمَرُونَ﴾؟","answer":"بعد نفي الاستكبار أثبت كمال الامتثال العملي؛ خوفهم يثمر طاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص548-555.","url":""}]},{"id":"s16-83","number":83,"surah":16,"verses":[51],"verseLabel":"النحل: 51","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا تَتَّخِذُوا إِلَهَيْنِ اثْنَيْنِ﴾ مع أن التثنية مفهومة؟","answer":"«اثنين» يقرر العدد ويقطع أي تأويل، ثم يقابله بقصر الألوهية على واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص555-563.","url":""}]},{"id":"s16-84","number":84,"surah":16,"verses":[52],"verseLabel":"النحل: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَهُ الدِّينُ وَاصِبًا﴾؟","answer":"«واصبًا» أي دائمًا خالصًا؛ فالعبادة والطاعة لا تكونان موسميتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص563-571.","url":""}]},{"id":"s16-85","number":85,"surah":16,"verses":[53],"verseLabel":"النحل: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا بِكُمْ مِنْ نِعْمَةٍ فَمِنَ اللَّهِ﴾؟","answer":"«من» الاستغراقية مع الشرط تحصر أصل كل نعمة فيه، ثم تفضح اللجوء إليه عند الضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص571-581.","url":""}]},{"id":"s16-86","number":86,"surah":16,"verses":[53],"verseLabel":"النحل: 53","question":"ما سرّ التعبير في قوله تعالى: ﴿تَجْأَرُونَ﴾ لا تدعون؟","answer":"الجؤار صوت مرتفع مع تضرع، يصور سقوط دعوى الشرك عند الألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص578-583.","url":""}]},{"id":"s16-87","number":87,"surah":16,"verses":[54],"verseLabel":"النحل: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿إِذَا فَرِيقٌ مِنْكُمْ بِرَبِّهِمْ يُشْرِكُونَ﴾؟","answer":"«إذا» الفجائية تكشف سرعة انقلابهم بعد كشف الضر، وقدّم ﴿بربهم﴾ لتفظيع المقابلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص583-592.","url":""}]},{"id":"s16-88","number":88,"surah":16,"verses":[56],"verseLabel":"النحل: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَجْعَلُونَ لِمَا لَا يَعْلَمُونَ نَصِيبًا﴾؟","answer":"أبهم المعبودات تحقيرًا، ونفى عنها العلم أو نفى علم العابدين بحجة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص592-603.","url":""}]},{"id":"s16-89","number":89,"surah":16,"verses":[57],"verseLabel":"النحل: 57","question":"ما سرّ التعبير في قوله تعالى عن نسبة البنات: ﴿سُبْحَانَهُ﴾؟","answer":"قطع الحكاية بتنزيه فوري قبل ذكر ما يشتهون لأنفسهم، فظهرت بشاعة القسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص603-612.","url":""}]},{"id":"s16-90","number":90,"surah":16,"verses":[58],"verseLabel":"النحل: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿ظَلَّ وَجْهُهُ مُسْوَدًّا﴾؟","answer":"جعل السواد ملازمًا للوجه طوال حاله، فظهر التناقض بين كراهيته للبنت ونسبتها إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص612-623.","url":""}]},{"id":"s16-91","number":91,"surah":16,"verses":[59],"verseLabel":"النحل: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿يَتَوَارَى مِنَ الْقَوْمِ﴾؟","answer":"التواري تكلف الاختفاء، يصور العار الاجتماعي الذي صنعوه ثم أساؤوا الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص641-650.","url":""}]},{"id":"s16-92","number":92,"surah":16,"verses":[60],"verseLabel":"النحل: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ مَثَلُ السَّوْءِ﴾؟","answer":"جعل صفات النقص التي نسبوها لغيرهم راجعة إليهم، ولله وحده الوصف الأعلى.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص658-668.","url":""}]},{"id":"s16-93","number":93,"surah":16,"verses":[61],"verseLabel":"النحل: 61","question":"لماذا أخّر الناس إلى ﴿أَجَلٍ مُسَمًّى﴾؟","answer":"الأجل هو الحد المضروب، فيوازن بين العدل في الاستحقاق والرحمة في الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص681.","url":""}]},{"id":"s16-94","number":94,"surah":16,"verses":[62],"verseLabel":"النحل: 62","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَجْعَلُونَ لِلَّهِ مَا يَكْرَهُونَ﴾؟","answer":"حذف الشيء ليعم البنات والشركاء وكل وصف ينفرون منه لأنفسهم ثم ينسبونه لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص690-703.","url":""}]},{"id":"s16-95","number":95,"surah":16,"verses":[63],"verseLabel":"النحل: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿تَاللَّهِ لَقَدْ أَرْسَلْنَا﴾؟","answer":"القسم يثبت أن ما يواجهه النبي سنة رسالية قديمة، لا علامة فشل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص703-715.","url":""}]},{"id":"s16-96","number":96,"surah":16,"verses":[63],"verseLabel":"النحل: 63","question":"ما سرّ التعبير في قوله تعالى: ﴿فَزَيَّنَ لَهُمُ الشَّيْطَانُ أَعْمَالَهُمْ﴾؟","answer":"لم يخلق أفعالهم، بل حسنها في أعينهم حتى اختاروا الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص710-720.","url":""}]},{"id":"s16-97","number":97,"surah":16,"verses":[64],"verseLabel":"النحل: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿إِلَّا لِتُبَيِّنَ لَهُمُ الَّذِي اخْتَلَفُوا فِيهِ﴾؟","answer":"حصر وظيفة التنزيل هنا في كشف موضع النزاع، ثم جعله هدى ورحمة لمن يقبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص720-728.","url":""}]},{"id":"s16-98","number":98,"surah":16,"verses":[65],"verseLabel":"النحل: 65","question":"لماذا خُتمت بـ﴿لِقَوْمٍ يَسْمَعُونَ﴾؟","answer":"لأن الاعتبار بآية إحياء الأرض لا ينتفع به من لم يسمع الحق ويذعن له؛ فالمراد سماع القبول، إذ لا يبصر النظر المعاني بلا هداية مسموعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص729-730.","url":""}]},{"id":"s16-99","number":99,"surah":16,"verses":[66],"verseLabel":"النحل: 66","question":"لماذا جمع بين الفرث والدم واللبن؟","answer":"ليظهر إخراج شراب نقي سائغ من بين مواد مستقذرة متجاورة بلا اختلاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص735-748.","url":""}]},{"id":"s16-100","number":100,"surah":16,"verses":[67],"verseLabel":"النحل: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿تَتَّخِذُونَ مِنْهُ سَكَرًا وَرِزْقًا حَسَنًا﴾؟","answer":"قابل ما قد يُتخذ مسكرًا بما هو رزق حسن، تمهيدًا للتشريع وتنبيهًا إلى التفاوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص748-761.","url":""}]},{"id":"s16-101","number":101,"surah":16,"verses":[68],"verseLabel":"النحل: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿وَأَوْحَى رَبُّكَ إِلَى النَّحْلِ﴾؟","answer":"الوحي هنا إلهام فطري دقيق، وإضافة الرب إلى النبي تلفته إلى عناية واحدة بالرسالة والنحلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص761-774.","url":""}]},{"id":"s16-102","number":102,"surah":16,"verses":[68],"verseLabel":"النحل: 68","question":"لماذا جاءت ﴿النحل﴾ مؤنثة؟","answer":"اسم الجنس هنا يلحظ جماعة النحل، والعاملات اللاتي تبني وتجمع العسل إناث.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص768-776.","url":""}]},{"id":"s16-103","number":103,"surah":16,"verses":[68],"verseLabel":"النحل: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿اتَّخِذِي مِنَ الْجِبَالِ بُيُوتًا وَمِنَ الشَّجَرِ وَمِمَّا يَعْرِشُونَ﴾؟","answer":"رتب مساكنها من الطبيعي الأعلى والأصلب إلى الشجر ثم ما يصنعه البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص774-786.","url":""}]},{"id":"s16-104","number":104,"surah":16,"verses":[69],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلِي مِنْ كُلِّ الثَّمَرَاتِ﴾ مع أنها لا تأكل الثمار كلها؟","answer":"«من» تبعيضية؛ تأخذ من أنواع الزهر والثمر ما هيئ لها، لا استغراق كل ثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص786-796.","url":""}]},{"id":"s16-105","number":105,"surah":16,"verses":[69],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاسْلُكِي سُبُلَ رَبِّكِ ذُلُلًا﴾؟","answer":"صوّر مسالك النحل التي هداها الله إليها سبلًا مذللة ميسرة، ويجوز أن تكون ﴿ذُلُلًا﴾ وصفًا للنحل؛ أي منقادة لما ألهمها ربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص792-801.","url":""}]},{"id":"s16-106","number":106,"surah":16,"verses":[69],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْرُجُ مِنْ بُطُونِهَا شَرَابٌ﴾، دون أن يقال عسل؟","answer":"عُبّر عن العسل بـ﴿شراب﴾ لما يومئ إليه اسم الجنس من الانتفاع به، وليترتب عليه بيان ما أودعه الله فيه من الشفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج26، ص766–767.","url":""}]},{"id":"s16-107","number":107,"surah":16,"verses":[69],"verseLabel":"النحل: 69","question":"ما سرّ التعبير في قوله تعالى: ﴿مُخْتَلِفٌ أَلْوَانُهُ﴾؟","answer":"تنوع اللون علامة على اختلاف المرعى والتركيب مع وحدة الصانع والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص15-25","url":""}]},{"id":"s16-108","number":108,"surah":16,"verses":[69],"verseLabel":"النحل: 69","question":"لماذا خُتمت آية النحل بـ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن نظام البيوت والمسالك وتحويل الرحيق إلى شفاء سلسلة عجيبة تحتاج تفكرًا متصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص15–25.","url":""}]},{"id":"s16-109","number":109,"surah":16,"verses":[70],"verseLabel":"النحل: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿وَاللَّهُ خَلَقَكُمْ ثُمَّ يَتَوَفَّاكُمْ﴾؟","answer":"جمع البداية والنهاية في قبضته، ثم عرض تفاوت الأعمار بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص25-38","url":""}]},{"id":"s16-110","number":110,"surah":16,"verses":[70],"verseLabel":"النحل: 70","question":"ما سرّ التعبير في قوله تعالى: ﴿أَرْذَلِ الْعُمُرِ﴾؟","answer":"ليس ذمًا للمعمر، بل وصف لمرحلة يضعف فيها ما كان كمالًا من العلم والقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص31-40","url":""}]},{"id":"s16-111","number":111,"surah":16,"verses":[71],"verseLabel":"النحل: 71","question":"ما سرّ التعبير في قوله تعالى: ﴿فَمَا الَّذِينَ فُضِّلُوا بِرَادِّي رِزْقِهِمْ﴾؟","answer":"حجة من واقع الملك: البشر لا يسوون مماليكهم بأنفسهم، فكيف يجعلون مخلوقات الله شركاء له؟","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص40-52","url":""}]},{"id":"s16-112","number":112,"surah":16,"verses":[72],"verseLabel":"النحل: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ أَنْفُسِكُمْ أَزْوَاجًا﴾؟","answer":"الاتحاد في الجنس أدعى للسكن والمودة والفهم، فجاءت النعمة من داخل طبيعتكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص52-64","url":""}]},{"id":"s16-113","number":113,"surah":16,"verses":[72],"verseLabel":"النحل: 72","question":"ما سرّ التعبير في قوله تعالى: ﴿بَنِينَ وَحَفَدَةً﴾؟","answer":"جمع الذرية القريبة ومن يسرع في الخدمة والنصرة، فاستوعب امتداد الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص58-68","url":""}]},{"id":"s16-114","number":114,"surah":16,"verses":[73],"verseLabel":"النحل: 73","question":"ما سرّ التعبير في قوله تعالى: ﴿عَبْدًا مَمْلُوكًا لَا يَقْدِرُ عَلَى شَيْءٍ﴾؟","answer":"جمع وصف الملك والعجز ليقيم أبسط مثل على بطلان تسوية المخلوق بالخالق الرازق.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص68-80","url":""}]},{"id":"s16-115","number":115,"surah":16,"verses":[75],"verseLabel":"النحل: 75","question":"لماذا ضرب مثل الأبكم؟","answer":"لأن العاجز عن البيان والفعل والإنفاق لا يستوي بمن يأمر بالعدل ويسير على صراط مستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص80-92","url":""}]},{"id":"s16-116","number":116,"surah":16,"verses":[77],"verseLabel":"النحل: 77","question":"ما سرّ تقديم غيب السماوات والأرض قبل أمر الساعة؟","answer":"من انفرد بعلم الغيب يعلم توقيت الساعة، ومن قدر على الكون يأتي بها كلمح البصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص92-104","url":""}]},{"id":"s16-117","number":117,"surah":16,"verses":[77],"verseLabel":"النحل: 77","question":"ما سرّ التعبير في قوله تعالى في الساعة: ﴿كَلَمْحِ الْبَصَرِ أَوْ هُوَ أَقْرَبُ﴾؟","answer":"تقريب لسرعة وقوعها، ثم ترقٍ ينفي أن يقيدها حتى مقدار اللمح.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص104-122","url":""}]},{"id":"s16-118","number":118,"surah":16,"verses":[77],"verseLabel":"النحل: 77","question":"لماذا خُصت الساعة بالذكر؟","answer":"لأنها أعظم غيب جادلوا فيه، ووقوعها يطوي نظام العالم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص122","url":""}]},{"id":"s16-119","number":119,"surah":16,"verses":[78],"verseLabel":"النحل: 78","question":"لماذا بدأ السمع قبل الأبصار والأفئدة؟","answer":"السمع أول منافذ التعلم في الطفل، ويعمل قبل البصر ومن جهات متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص122-138","url":""}]},{"id":"s16-120","number":120,"surah":16,"verses":[79],"verseLabel":"النحل: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿مُسَخَّرَاتٍ فِي جَوِّ السَّمَاءِ﴾؟","answer":"يصور الطير ممسوكًا في فراغ لا دعامة فيه إلا سنن الله وتسخيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص138-162","url":""}]},{"id":"s16-121","number":121,"surah":16,"verses":[79],"verseLabel":"النحل: 79","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا يُمْسِكُهُنَّ إِلَّا اللَّهُ﴾؟","answer":"نفي واستثناء يقصران حفظ نظام الطيران عليه، مع بقاء الأسباب التي خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص161","url":""}]},{"id":"s16-122","number":122,"surah":16,"verses":[80],"verseLabel":"النحل: 80","question":"لماذا سمى البيوت ﴿سَكَنًا﴾؟","answer":"انتقل من البناء المادي إلى غايته النفسية: الطمأنينة والاستقرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص162-176","url":""}]},{"id":"s16-123","number":123,"surah":16,"verses":[81],"verseLabel":"النحل: 81","question":"لماذا اكتفى بذكر الحر في ﴿سَرَابِيلَ تَقِيكُمُ الْحَرَّ﴾ ولم يذكر البرد؟","answer":"ذكر أحد الضدين يغني عن الآخر، والحر أشد حضورًا عند المخاطبين الأولين.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص176-205","url":""}]},{"id":"s16-124","number":124,"surah":16,"verses":[81],"verseLabel":"النحل: 81","question":"ما سرّ التعبير في قوله تعالى: ﴿سَرَابِيلَ تَقِيكُمْ بَأْسَكُمْ﴾؟","answer":"نقل الثياب من ستر البدن إلى الدروع التي تقي شدة الحرب، فجمع نعم السلم والقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص201-214","url":""}]},{"id":"s16-125","number":125,"surah":16,"verses":[83],"verseLabel":"النحل: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿يَعْرِفُونَ نِعْمَتَ اللَّهِ ثُمَّ يُنْكِرُونَهَا﴾؟","answer":"«ثم» تستبعد الانتقال من المعرفة الواضحة إلى الجحود، فهو مفارقة مقصودة لا جهل بسيط.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص214-230","url":""}]},{"id":"s16-126","number":126,"surah":16,"verses":[84],"verseLabel":"النحل: 84","question":"لماذا يبعث الله ﴿مِنْ كُلِّ أُمَّةٍ شَهِيدًا﴾؟","answer":"لتقوم الحجة من داخل كل أمة برسولها الذي بلغها وعرف استجابتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص230-246","url":""}]},{"id":"s16-127","number":127,"surah":16,"verses":[86],"verseLabel":"النحل: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وَرَأَى الَّذِينَ أَشْرَكُوا شُرَكَاءَهُمْ﴾؟","answer":"الإضافة تهكمية: يرون من نسبوهم لأنفسهم شركاء عاجزين يتبرؤون منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص246-260","url":""}]},{"id":"s16-128","number":128,"surah":16,"verses":[88],"verseLabel":"النحل: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿زِدْنَاهُمْ عَذَابًا فَوْقَ الْعَذَابِ﴾؟","answer":"زيادة العذاب تقابل زيادة إفسادهم بصد غيرهم، لا كفر أنفسهم فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص269-270","url":""}]},{"id":"s16-129","number":129,"surah":16,"verses":[88],"verseLabel":"النحل: 88","question":"لماذا ختم بـ﴿بِمَا كَانُوا يُفْسِدُونَ﴾ لا يكفرون؟","answer":"الفساد يشمل كفرهم وإضلالهم الناس وآثار ذلك في المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص269-270","url":""}]},{"id":"s16-130","number":130,"surah":16,"verses":[89],"verseLabel":"النحل: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿وَنَزَّلْنَا عَلَيْكَ الْكِتَابَ تِبْيَانًا لِكُلِّ شَيْءٍ﴾ بصيغة نزّل؟","answer":"التفعيل يلائم نزوله منجمًا متكرر البيان بحسب الوقائع.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص276-280","url":""}]},{"id":"s16-131","number":131,"surah":16,"verses":[89],"verseLabel":"النحل: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿تِبْيَانًا﴾ لا بيانًا؟","answer":"زيادة المبنى تلائم سعة الكشف وشموله لما تحتاجه الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص280","url":""}]},{"id":"s16-132","number":132,"surah":16,"verses":[89],"verseLabel":"النحل: 89","question":"لماذا رُتبت أوصاف الكتاب: تبيانًا وهدى ورحمة وبشرى؟","answer":"التبيان أساس المعرفة، فينشأ عنه الهدى، وتثمر الهداية الرحمة، ثم تأتي البشرى بعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص281-282","url":""}]},{"id":"s16-133","number":133,"surah":16,"verses":[90],"verseLabel":"النحل: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالْإِحْسَانِ﴾؟","answer":"ذكر اسم الجلالة للمهابة، وجمع الحد الواجب «العدل» والفضل الزائد «الإحسان».","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص287-292","url":""}]},{"id":"s16-134","number":134,"surah":16,"verses":[90],"verseLabel":"النحل: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿ذِي الْقُرْبَى﴾ بالإفراد؟","answer":"«ذي» اسم جنس يعم كل صاحب قرابة، فيستغرق الأفراد بلفظ موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص292","url":""}]},{"id":"s16-135","number":135,"surah":16,"verses":[90],"verseLabel":"النحل: 90","question":"لماذا جمع بين الفحشاء والمنكر والبغي؟","answer":"الفحشاء قبيح الشهوة، والمنكر ما تنكره الشريعة والفطرة، والبغي اعتداء على الغير؛ فاستوعب أبواب الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص294-295","url":""}]},{"id":"s16-136","number":136,"surah":16,"verses":[90],"verseLabel":"النحل: 90","question":"لماذا ختم بـ﴿لَعَلَّكُمْ تَذَكَّرُونَ﴾؟","answer":"هذه الأصول معلومة في الفطرة، والمطلوب استرجاعها والعمل بها لا مجرد سماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص297-298","url":""}]},{"id":"s16-137","number":137,"surah":16,"verses":[91],"verseLabel":"النحل: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلَا تَنْقُضُوا الْأَيْمَانَ﴾ لا تنكثوا؟","answer":"النقض يصور العهد بناءً أو حبلًا محكمًا فُك بعد توثيقه، فهو أشد تصويرًا للخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص310","url":""}]},{"id":"s16-138","number":138,"surah":16,"verses":[91],"verseLabel":"النحل: 91","question":"ما سرّ التعبير في قوله تعالى: ﴿وَقَدْ جَعَلْتُمُ اللَّهَ عَلَيْكُمْ كَفِيلًا﴾؟","answer":"تقديم ﴿عليكم﴾ يشعر برقابة الكفيل وشهادته الملزمة فوقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص312","url":""}]},{"id":"s16-139","number":139,"surah":16,"verses":[92],"verseLabel":"النحل: 92","question":"لماذا شُبه ناقض العهد بالتي نقضت غزلها؟","answer":"صورة محسوسة لعمل يبطل صاحبه بيده ما تعب في إحكامه، فتظهر الحماقة قبل الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص321-327","url":""}]},{"id":"s16-140","number":140,"surah":16,"verses":[92],"verseLabel":"النحل: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْ تَكُونَ أُمَّةٌ هِيَ أَرْبَى مِنْ أُمَّةٍ﴾؟","answer":"يكشف دافع الخيانة: الانحياز للأقوى والأكثر طلبًا لمصلحة متقلبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص323-328","url":""}]},{"id":"s16-141","number":141,"surah":16,"verses":[92],"verseLabel":"النحل: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّمَا يَبْلُوكُمُ اللَّهُ بِهِ﴾؟","answer":"فصل الجملة لتكشف أن تفاوت القوة اختبار للوفاء لا مبرر لنقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص327-328","url":""}]},{"id":"s16-142","number":142,"surah":16,"verses":[94],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿فَتَزِلَّ قَدَمٌ بَعْدَ ثُبُوتِهَا﴾؟","answer":"استعار زلة القدم لانحراف النفس بعد رسوخها في الحق، فصوّر خطر الانتكاس فجأة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص346-354","url":""}]},{"id":"s16-143","number":143,"surah":16,"verses":[94],"verseLabel":"النحل: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿بَعْدَ ثُبُوتِهَا﴾ لا ثباتها؟","answer":"الثبوت نفس تحقق الرسوخ قبل الزلة، أما الثبات فقد يلحظ دوام الحالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج27، ص354","url":""}]}]);
